import threading
import time
from collections import OrderedDict
from typing import Any, Optional


class TimeBoundedLRUCache:
    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        if capacity <= 0:
            raise ValueError("capacity must be greater than 0")
        self.capacity = capacity
        self.default_ttl_seconds = float(default_ttl_seconds)
        self._cache: OrderedDict[str, tuple[Any, float]] = OrderedDict()
        self._lock = threading.RLock()
        self.lock = self._lock

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        with self._lock:
            now = time.monotonic()
            ttl_seconds = self.default_ttl_seconds if ttl is None else float(ttl)
            expires_at = now + ttl_seconds

            if key in self._cache:
                self._cache[key] = (value, expires_at)
                self._cache.move_to_end(key)
                return

            if len(self._cache) >= self.capacity:
                evict_key = None
                # Evict the least recently used NON-EXPIRED item
                for k, (_, exp) in self._cache.items():
                    if exp > now:
                        evict_key = k
                        break

                # If all items in the cache are expired, evict the oldest expired item
                if evict_key is None:
                    evict_key = min(self._cache.keys(), key=lambda k: self._cache[k][1])

                del self._cache[evict_key]

            self._cache[key] = (value, expires_at)

    def get(self, key: str) -> Optional[Any]:
        with self._lock:
            if key not in self._cache:
                return None

            val, expires_at = self._cache[key]
            now = time.monotonic()
            if expires_at <= now:
                return None

            self._cache.move_to_end(key)
            return val

    def delete(self, key: str) -> bool:
        with self._lock:
            if key in self._cache:
                del self._cache[key]
                return True
            return False

    def cleanup_expired(self) -> int:
        with self._lock:
            now = time.monotonic()
            expired_keys = [k for k, (_, exp) in self._cache.items() if exp <= now]
            for k in expired_keys:
                del self._cache[k]
            return len(expired_keys)

    def size(self) -> int:
        with self._lock:
            now = time.monotonic()
            return sum(1 for _, (_, exp) in self._cache.items() if exp > now)

    def __len__(self) -> int:
        return self.size()
