class CircularDependencyError(Exception):
    """Exception raised when a circular dependency is detected."""
    pass


class DependencyResolver:
    @staticmethod
    def resolve(dependencies: dict[str, list[str]]) -> list[list[str]]:
        """
        Resolves task dependencies into sequential execution stages.

        Each stage contains a sorted list of task names that can run in parallel.
        Tasks with no dependencies execute in stage 0.

        Raises CircularDependencyError if a circular dependency exists.
        """
        # Collect all unique tasks from both keys and dependency lists
        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        if not all_tasks:
            return []

        # Track in-degrees (number of unmet dependencies) and forward adjacency
        in_degree = {task: 0 for task in all_tasks}
        dependents: dict[str, set[str]] = {task: set() for task in all_tasks}

        for task, deps in dependencies.items():
            unique_deps = set(deps)
            in_degree[task] = len(unique_deps)
            for dep in unique_deps:
                dependents[dep].add(task)

        # Stage 0: tasks with no dependencies
        current_stage = [task for task, deg in in_degree.items() if deg == 0]
        stages: list[list[str]] = []
        resolved_count = 0

        while current_stage:
            current_stage.sort()
            stages.append(current_stage)
            resolved_count += len(current_stage)

            next_stage = []
            for task in current_stage:
                for dependent in dependents[task]:
                    in_degree[dependent] -= 1
                    if in_degree[dependent] == 0:
                        next_stage.append(dependent)
            current_stage = next_stage

        if resolved_count < len(all_tasks):
            raise CircularDependencyError("Circular dependency detected among tasks.")

        return stages
