import bisect
import threading
import time
from collections import deque
from typing import Optional


class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window_seconds = float(window_seconds)
        self._lock = threading.Lock()
        self._requests: dict[str, deque[float]] = {}

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        with self._lock:
            if self.max_requests <= 0:
                return False, float(self.window_seconds)

            current_time = time.time() if timestamp is None else float(timestamp)
            cutoff = current_time - self.window_seconds

            dq = self._requests.get(key)
            if dq is None:
                dq = deque()
                self._requests[key] = dq
            else:
                while dq and dq[0] <= cutoff:
                    dq.popleft()

            if len(dq) < self.max_requests:
                if not dq or current_time >= dq[-1]:
                    dq.append(current_time)
                else:
                    idx = bisect.bisect_right(dq, current_time)
                    dq.insert(idx, current_time)
                return True, 0.0

            retry_after = (dq[len(dq) - self.max_requests] + self.window_seconds) - current_time
            return False, max(0.0, retry_after)

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        with self._lock:
            if self.max_requests <= 0:
                return 0

            dq = self._requests.get(key)
            if not dq:
                return self.max_requests

            if timestamp is None:
                current_time = time.time()
                cutoff = current_time - self.window_seconds
                while dq and dq[0] <= cutoff:
                    dq.popleft()
                if not dq:
                    del self._requests[key]
                    return self.max_requests
                return max(0, self.max_requests - len(dq))
            else:
                current_time = float(timestamp)
                cutoff = current_time - self.window_seconds
                idx_left = bisect.bisect_right(dq, cutoff)
                idx_right = bisect.bisect_right(dq, current_time)
                active_count = max(0, idx_right - idx_left)
                return max(0, self.max_requests - active_count)
