import asyncio
import itertools
from typing import Any, Callable, Optional


class _QueueItem:
    """Internal wrapper for items stored in the priority queue."""

    __slots__ = ("priority", "count", "coro_func", "args", "kwargs", "future")

    def __init__(
        self,
        priority: int,
        count: int,
        coro_func: Callable[..., Any],
        args: tuple,
        kwargs: dict,
        future: asyncio.Future,
    ) -> None:
        self.priority = priority
        self.count = count
        self.coro_func = coro_func
        self.args = args
        self.kwargs = kwargs
        self.future = future

    def __lt__(self, other: "_QueueItem") -> bool:
        if self.priority != other.priority:
            # Higher priority integer executes before lower priority integers
            return self.priority > other.priority
        # Preserve FIFO order for items with equal priority
        return self.count < other.count


class AsyncWorkerPool:
    """An asynchronous worker pool with priority scheduling, concurrency control,

    and graceful/immediate shutdown handling.
    """

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency <= 0:
            raise ValueError("concurrency must be greater than 0")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be non-negative")

        self.concurrency = concurrency
        self.max_queue_size = max_queue_size

        self._queue: asyncio.PriorityQueue[_QueueItem] = asyncio.PriorityQueue(
            maxsize=max_queue_size
        )
        self._workers: list[asyncio.Task] = []
        self._counter = itertools.count()
        self._started: bool = False
        self._is_shutting_down: bool = False
        self._closed: bool = False
        self._shutdown_event: asyncio.Event = asyncio.Event()
        self._shutdown_lock: asyncio.Lock = asyncio.Lock()

    async def start(self) -> None:
        """Spawns worker tasks to process items from the queue."""
        if self._is_shutting_down or self._closed:
            raise RuntimeError("Pool is shutting down")
        if self._started:
            return

        self._started = True
        self._workers = [
            asyncio.create_task(
                self._worker_loop(), name=f"AsyncWorkerPool-worker-{i}"
            )
            for i in range(self.concurrency)
        ]

    async def submit(
        self, coro_func: Callable[..., Any], *args, priority: int = 0, **kwargs
    ) -> asyncio.Future:
        """Enqueues a coroutine function coro_func(*args, **kwargs) to be executed by workers.

        Higher priority integer executes before lower priority integers.
        Returns an asyncio.Future resolving with the result (or exception).
        """
        if self._is_shutting_down or self._closed:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        future: asyncio.Future = loop.create_future()
        item = _QueueItem(
            priority, next(self._counter), coro_func, args, kwargs, future
        )

        try:
            self._queue.put_nowait(item)
            return future
        except asyncio.QueueFull:
            pass

        # If queue is full, wait for space to open or shutdown to be triggered
        put_task = asyncio.create_task(self._queue.put(item))
        shutdown_waiter = asyncio.create_task(self._shutdown_event.wait())
        try:
            done, pending = await asyncio.wait(
                [put_task, shutdown_waiter],
                return_when=asyncio.FIRST_COMPLETED,
            )
            if self._shutdown_event.is_set():
                if not future.done():
                    future.cancel()
                raise RuntimeError("Pool is shutting down")
            return future
        finally:
            for task in (put_task, shutdown_waiter):
                if not task.done():
                    task.cancel()
                    try:
                        await task
                    except asyncio.CancelledError:
                        pass

    async def _worker_loop(self) -> None:
        """Worker loop that continuously fetches and runs tasks from the queue."""
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            future = item.future
            # If the caller cancelled the future before it started, skip execution
            if future.done():
                self._queue.task_done()
                continue

            try:
                res = item.coro_func(*item.args, **item.kwargs)
                if asyncio.iscoroutine(res):
                    res = await res
                if not future.done():
                    future.set_result(res)
            except asyncio.CancelledError:
                if not future.done():
                    future.cancel()
                current_task = asyncio.current_task()
                if self._is_shutting_down or (
                    current_task is not None and current_task.cancelling() > 0
                ):
                    raise
            except Exception as exc:
                if not future.done():
                    future.set_exception(exc)
            except BaseException as exc:
                if not future.done():
                    future.set_exception(exc)
                raise
            finally:
                self._queue.task_done()

    def _cancel_queued_tasks(self) -> None:
        """Empties the queue and cancels the futures of all pending tasks."""
        while not self._queue.empty():
            try:
                item = self._queue.get_nowait()
            except asyncio.QueueEmpty:
                break
            if not item.future.done():
                item.future.cancel()
            self._queue.task_done()

    async def shutdown(
        self, drain: bool = True, timeout: Optional[float] = 5.0
    ) -> None:
        """Shuts down the pool.

        If drain=True, waits for all currently enqueued tasks to complete before stopping workers.
        If drain=False, cancels all queued and currently executing tasks immediately.
        Respects optional timeout seconds.
        """
        async with self._shutdown_lock:
            if self._closed:
                return

            self._is_shutting_down = True
            self._shutdown_event.set()

            # If workers were not yet started and there are tasks to drain, spawn them
            if not self._started and drain and not self._queue.empty():
                self._started = True
                self._workers = [
                    asyncio.create_task(
                        self._worker_loop(), name=f"AsyncWorkerPool-worker-{i}"
                    )
                    for i in range(self.concurrency)
                ]

            if drain:
                async def _drain_and_stop():
                    # Wait for all tasks in the queue to be completed
                    await self._queue.join()
                    # Stop idle workers waiting on queue.get()
                    for worker in self._workers:
                        if not worker.done():
                            worker.cancel()
                    if self._workers:
                        await asyncio.gather(*self._workers, return_exceptions=True)
                        self._workers.clear()

                try:
                    if timeout is not None:
                        await asyncio.wait_for(_drain_and_stop(), timeout=timeout)
                    else:
                        await _drain_and_stop()
                except (asyncio.TimeoutError, TimeoutError):
                    # Drain timed out; forcibly cancel remaining tasks and stop workers cleanly
                    self._cancel_queued_tasks()
                    for worker in self._workers:
                        if not worker.done():
                            worker.cancel()
                    if self._workers:
                        await asyncio.gather(*self._workers, return_exceptions=True)
                        self._workers.clear()
                    self._closed = True
                    raise
                else:
                    self._closed = True
            else:
                # Cancel queued tasks immediately
                self._cancel_queued_tasks()
                # Cancel all currently executing worker tasks
                for worker in self._workers:
                    if not worker.done():
                        worker.cancel()

                if self._workers:
                    gather_task = asyncio.gather(
                        *self._workers, return_exceptions=True
                    )
                    try:
                        if timeout is not None:
                            await asyncio.wait_for(gather_task, timeout=timeout)
                        else:
                            await gather_task
                    except (asyncio.TimeoutError, TimeoutError):
                        raise
                    finally:
                        self._workers.clear()
                        self._closed = True
                else:
                    self._closed = True

    async def __aenter__(self) -> "AsyncWorkerPool":
        await self.start()
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb) -> None:
        await self.shutdown(drain=(exc_type is None))
