class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        """
        Initializes cluster state with given unique node IDs.
        Total node count N = len(node_ids). Quorum threshold is floor(N / 2) + 1.
        """
        self.node_ids: list[str] = list(node_ids)
        self.N: int = len(self.node_ids)
        self.quorum_threshold: int = (self.N // 2) + 1

        # Local storage for each individual node: node_id -> {key: value}
        self._node_states: dict[str, dict[str, any]] = {nid: {} for nid in self.node_ids}

        # Cluster-wide canonical committed state for synchronization upon healing
        self._committed_state: dict[str, any] = {}

        # Network partitions: node_id -> set of reachable node_ids
        all_nodes = set(self.node_ids)
        self._partitions: dict[str, set[str]] = {nid: all_nodes for nid in self.node_ids}

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """
        Divides cluster into isolated network partitions where nodes in group_a
        can only talk to group_a, and group_b only to group_b.
        Any nodes not in group_a or group_b remain in their own isolated partition.
        """
        set_a = set(group_a) & set(self.node_ids)
        set_b = (set(group_b) & set(self.node_ids)) - set_a

        self._partitions = {}
        for nid in self.node_ids:
            if nid in set_a:
                self._partitions[nid] = set_a
            elif nid in set_b:
                self._partitions[nid] = set_b
            else:
                self._partitions[nid] = {nid}

    def heal_partition(self) -> None:
        """
        Restores full connectivity so all nodes can communicate,
        synchronizing committed state across all nodes.
        """
        all_nodes = set(self.node_ids)
        self._partitions = {nid: all_nodes for nid in self.node_ids}

        # Synchronize committed state to all nodes in the cluster
        for nid in self.node_ids:
            self._node_states[nid] = dict(self._committed_state)

    def propose_write(self, from_node: str, key: str, value: any) -> bool:
        """
        Proposes a write from from_node.
        If from_node belongs to a partition having a STRICT MAJORITY
        (active partition size >= quorum threshold), the write commits,
        updates state in all nodes within that partition, and returns True.
        If from_node is in a MINORITY partition (< quorum threshold),
        the write is REJECTED (returns False).
        """
        if from_node not in self._partitions:
            return False

        active_partition = self._partitions[from_node]
        if len(active_partition) >= self.quorum_threshold:
            self._committed_state[key] = value
            for nid in active_partition:
                self._node_states[nid][key] = value
            return True

        return False

    def read_value(self, from_node: str, key: str) -> any:
        """
        Returns the committed value for key on from_node (or None if not set).
        """
        if from_node not in self._node_states:
            return None
        return self._node_states[from_node].get(key, None)
