import threading


class ResilientConnectionPool:
    """A thread-safe, resilient database connection pool wrapper."""

    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0) -> None:
        """Initialize the connection pool with a maximum connection limit and ping timeout.

        Args:
            max_connections: Maximum number of connections allowed in the pool.
            ping_timeout: Timeout in seconds for connection health checks.
        """
        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._lock = threading.RLock()
        self._closed = False
        self._pool: list[dict] = [
            {"id": i + 1, "alive": True} for i in range(max_connections)
        ]

    @property
    def pool(self) -> list[dict]:
        """Access the underlying connection list."""
        return self._pool

    @pool.setter
    def pool(self, value: list[dict]) -> None:
        self._pool = value

    @property
    def connections(self) -> list[dict]:
        """Alias for the connection pool list."""
        return self._pool

    @connections.setter
    def connections(self, value: list[dict]) -> None:
        self._pool = value

    def acquire(self) -> dict:
        """Acquire an active connection from the pool.

        Returns:
            An active connection dictionary in the format {"id": int, "alive": bool}.

        Raises:
            RuntimeError: If no connections are available in the pool.
        """
        with self._lock:
            if self._closed or not self._pool:
                raise RuntimeError("Pool exhausted")
            return self._pool.pop(0)

    def release(self, conn: dict) -> None:
        """Return an acquired connection back to the pool.

        Args:
            conn: Connection dictionary to return to the pool.
        """
        with self._lock:
            if self._closed or not isinstance(conn, dict):
                return
            # Prevent duplicate releases
            if any(
                c is conn
                or (c.get("id") is not None and c.get("id") == conn.get("id"))
                for c in self._pool
            ):
                return
            if len(self._pool) < self.max_connections:
                self._pool.append(conn)

    def health_check_and_heal(self) -> int:
        """Iterate over pool connections, check if any are dead, and recreate them.

        Returns:
            The number of healed connections.
        """
        with self._lock:
            healed = 0
            for i, conn in enumerate(self._pool):
                if not conn.get("alive", False):
                    self._pool[i] = {"id": conn.get("id", i + 1), "alive": True}
                    healed += 1
            return healed

    def close_all(self) -> None:
        """Close and empty the pool."""
        with self._lock:
            self._closed = True
            for conn in self._pool:
                if isinstance(conn, dict):
                    conn["alive"] = False
            self._pool.clear()

    def __len__(self) -> int:
        """Return the number of available connections in the pool."""
        with self._lock:
            return len(self._pool)
