import ast


def prune_dead_code_and_imports(source_code: str) -> str:
    tree = ast.parse(source_code)

    def is_top_level_private_fn(stmt):
        return (
            isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef))
            and stmt.name.startswith("_")
        )

    def get_referenced_names(node):
        names = set()
        for child in ast.walk(node):
            if isinstance(child, ast.Name):
                names.add(child.id)
            elif isinstance(child, (ast.Global, ast.Nonlocal)):
                names.update(child.names)
            elif (
                isinstance(child, (ast.MatchAs, ast.MatchStar))
                and getattr(child, "name", None)
            ):
                names.add(child.name)
            elif isinstance(child, ast.Assign):
                for target in child.targets:
                    if isinstance(target, ast.Name) and target.id == "__all__":
                        if hasattr(child.value, "elts"):
                            for elt in child.value.elts:
                                if isinstance(elt, ast.Constant) and isinstance(
                                    elt.value, str
                                ):
                                    names.add(elt.value)
            elif isinstance(child, (ast.AnnAssign, ast.AugAssign)):
                target = getattr(child, "target", None)
                if isinstance(target, ast.Name) and target.id == "__all__":
                    val = getattr(child, "value", None)
                    if val and hasattr(val, "elts"):
                        for elt in val.elts:
                            if isinstance(elt, ast.Constant) and isinstance(
                                elt.value, str
                            ):
                                names.add(elt.value)
        return names

    # 1. Prune dead top-level private functions via reachability analysis
    top_level_private = [
        stmt for stmt in tree.body if is_top_level_private_fn(stmt)
    ]

    # Live roots are all top-level statements that are not dead candidates
    live_names = set()
    for stmt in tree.body:
        if not is_top_level_private_fn(stmt):
            live_names.update(get_referenced_names(stmt))

    reachable_private_funcs = set()
    queue = list(live_names)
    while queue:
        current_name = queue.pop()
        for fn in top_level_private:
            if fn.name == current_name and fn not in reachable_private_funcs:
                reachable_private_funcs.add(fn)
                for ref_name in get_referenced_names(fn):
                    if ref_name not in live_names:
                        live_names.add(ref_name)
                        queue.append(ref_name)

    tree.body = [
        stmt
        for stmt in tree.body
        if not is_top_level_private_fn(stmt) or stmt in reachable_private_funcs
    ]

    # 2. Prune unused imports across the remaining AST
    used_names = set()
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            continue
        if isinstance(node, ast.Name):
            used_names.add(node.id)
        elif isinstance(node, (ast.Global, ast.Nonlocal)):
            used_names.update(node.names)
        elif (
            isinstance(node, (ast.MatchAs, ast.MatchStar))
            and getattr(node, "name", None)
        ):
            used_names.add(node.name)
        elif isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id == "__all__":
                    if hasattr(node.value, "elts"):
                        for elt in node.value.elts:
                            if isinstance(elt, ast.Constant) and isinstance(
                                elt.value, str
                            ):
                                used_names.add(elt.value)
        elif isinstance(node, (ast.AnnAssign, ast.AugAssign)):
            target = getattr(node, "target", None)
            if isinstance(target, ast.Name) and target.id == "__all__":
                val = getattr(node, "value", None)
                if val and hasattr(val, "elts"):
                    for elt in val.elts:
                        if isinstance(elt, ast.Constant) and isinstance(
                            elt.value, str
                        ):
                            used_names.add(elt.value)

    class ImportPruner(ast.NodeTransformer):
        def visit_Import(self, node):
            new_names = []
            for alias in node.names:
                bound = (
                    alias.asname
                    if alias.asname
                    else alias.name.split(".")[0]
                )
                if bound in used_names:
                    new_names.append(alias)
            if not new_names:
                return None
            node.names = new_names
            return node

        def visit_ImportFrom(self, node):
            if getattr(node, "module", None) == "__future__":
                return node
            new_names = []
            for alias in node.names:
                bound = alias.asname if alias.asname else alias.name
                if bound == "*" or bound in used_names:
                    new_names.append(alias)
            if not new_names:
                return None
            node.names = new_names
            return node

    tree = ImportPruner().visit(tree)

    # Ensure all block bodies remain syntactically valid after potential import removals
    for child in ast.walk(tree):
        if hasattr(child, "body") and not isinstance(child, ast.Module):
            if isinstance(child.body, list) and len(child.body) == 0:
                child.body = [ast.Pass()]
        if isinstance(child, (ast.Try, getattr(ast, "TryStar", ()))):
            if len(child.handlers) == 0 and len(child.finalbody) == 0:
                child.finalbody = [ast.Pass()]

    ast.fix_missing_locations(tree)
    result = ast.unparse(tree)
    compile(result, "<string>", "exec")
    return result
