import posixpath
import re
import stat
import unicodedata
import zipfile
from pathlib import PurePosixPath, PureWindowsPath


def safe_extract_zip(
    archive_path: str,
    destination: str,
    max_files: int = 1000,
    max_uncompressed_bytes: int = 10000000,
    max_compression_ratio: float = 100.0,
) -> list[str]:
    try:
        zf = zipfile.ZipFile(archive_path, "r")
    except (zipfile.BadZipFile, zipfile.LargeZipFile) as err:
        raise ValueError(f"Invalid zip archive: {err}") from err

    with zf:
        infolist = zf.infolist()

        def is_symlink(info: zipfile.ZipInfo) -> bool:
            mode = info.external_attr >> 16
            return stat.S_ISLNK(mode)

        def is_dir_entry(info: zipfile.ZipInfo) -> bool:
            if info.is_dir():
                return True
            if info.filename.endswith(("/", "\\")):
                return True
            mode = info.external_attr >> 16
            if stat.S_ISDIR(mode):
                return True
            return False

        def is_absolute(name: str) -> bool:
            if name.startswith(("/", "\\")):
                return True
            if bool(re.match(r"^[a-zA-Z]:", name)):
                return True
            p_win = PureWindowsPath(name)
            if p_win.is_absolute() or p_win.drive:
                return True
            if PurePosixPath(name).is_absolute():
                return True
            return False

        def escapes_destination(name: str, dest_dir: str) -> bool:
            norm_slash = name.replace("\\", "/")
            parts = [p for p in norm_slash.split("/") if p]
            depth = 0
            for p in parts:
                if p == ".":
                    continue
                if p == "..":
                    depth -= 1
                    if depth < 0:
                        return True
                else:
                    depth += 1
            if depth <= 0:
                return True

            norm_posix = posixpath.normpath(norm_slash)
            if norm_posix == "." or norm_posix == ".." or norm_posix.startswith("../"):
                return True

            dest_abs = os.path.abspath(dest_dir)
            target_abs = os.path.abspath(os.path.join(dest_abs, *norm_posix.split("/")))
            if os.path.commonpath([dest_abs, target_abs]) != dest_abs or target_abs == dest_abs:
                return True

            return False

        # Phase 1: Validate entire archive before writing anything
        file_count = 0
        total_uncompressed = 0
        seen_nfc_names = set()
        seen_posix_paths = set()
        file_paths = set()

        for info in infolist:
            raw_name = getattr(info, "orig_filename", "") or info.filename

            # Check for NUL byte
            if "\0" in raw_name or "\0" in info.filename:
                raise ValueError(f"Entry contains NUL byte: {raw_name!r}")

            # Check for Unix symlink
            if is_symlink(info):
                raise ValueError(f"Entry is a Unix symlink: {raw_name!r}")

            # Check for absolute path
            if is_absolute(raw_name) or is_absolute(info.filename):
                raise ValueError(f"Entry is absolute: {raw_name!r}")

            # Check for directory traversal escaping destination
            if escapes_destination(raw_name, destination) or escapes_destination(info.filename, destination):
                raise ValueError(f"Entry escapes destination through '..': {raw_name!r}")

            # Unicode NFC normalization collision check
            nfc_name = unicodedata.normalize("NFC", raw_name)
            if nfc_name in seen_nfc_names:
                raise ValueError(f"Entry collides with another name after Unicode NFC normalization: {raw_name!r}")
            seen_nfc_names.add(nfc_name)

            # POSIX relative path collision check
            norm_posix = unicodedata.normalize("NFC", posixpath.normpath(raw_name.replace("\\", "/")))
            if norm_posix.startswith("./"):
                norm_posix = norm_posix[2:]

            if norm_posix in seen_posix_paths:
                raise ValueError(f"Entry path collides after normalization: {raw_name!r}")
            seen_posix_paths.add(norm_posix)

            is_dir = is_dir_entry(info)

            if info.file_size < 0:
                raise ValueError(f"Negative uncompressed file size: {raw_name!r}")
            total_uncompressed += info.file_size

            if not is_dir:
                file_count += 1

                # Check per-file compression ratio
                if info.compress_size < 0:
                    raise ValueError(f"Negative compressed file size: {raw_name!r}")
                if info.file_size > 0 and info.compress_size == 0:
                    raise ValueError(f"Infinite compression ratio: {raw_name!r}")
                if info.compress_size > 0:
                    ratio = info.file_size / info.compress_size
                    if ratio > max_compression_ratio:
                        raise ValueError(
                            f"Compression ratio {ratio} exceeds limit {max_compression_ratio}: {raw_name!r}"
                        )

                # Check path hierarchy conflicts with files
                parts = norm_posix.split("/")
                for i in range(1, len(parts)):
                    parent = "/".join(parts[:i])
                    if parent in file_paths:
                        raise ValueError(f"File path conflicts with parent file: {raw_name!r}")
                for existing in file_paths:
                    if existing.startswith(norm_posix + "/"):
                        raise ValueError(f"File path conflicts with existing child file: {raw_name!r}")
                file_paths.add(norm_posix)

        # Check archive-wide limits
        if file_count > max_files:
            raise ValueError(f"File count {file_count} exceeds limit of {max_files}")

        if total_uncompressed > max_uncompressed_bytes:
            raise ValueError(
                f"Cumulative uncompressed bytes {total_uncompressed} exceeds limit of {max_uncompressed_bytes}"
            )

        # Phase 2: Extract archive entries beneath destination
        dest_abs = os.path.abspath(destination)
        os.makedirs(dest_abs, exist_ok=True)

        extracted_files = []
        created_files = []
        created_dirs = []

        try:
            for info in infolist:
                raw_name = getattr(info, "orig_filename", "") or info.filename
                is_dir = is_dir_entry(info)
                norm_posix = unicodedata.normalize("NFC", posixpath.normpath(raw_name.replace("\\", "/")))
                if norm_posix.startswith("./"):
                    norm_posix = norm_posix[2:]

                target_path = os.path.abspath(os.path.join(dest_abs, *norm_posix.split("/")))

                if is_dir:
                    if not os.path.exists(target_path):
                        created_dirs.append(target_path)
                    os.makedirs(target_path, exist_ok=True)
                else:
                    parent_dir = os.path.dirname(target_path)
                    curr = parent_dir
                    new_parents = []
                    while curr and curr != dest_abs and not os.path.exists(curr):
                        new_parents.append(curr)
                        curr = os.path.dirname(curr)
                    for d in reversed(new_parents):
                        created_dirs.append(d)
                        os.makedirs(d, exist_ok=True)

                    if not os.path.exists(target_path):
                        created_files.append(target_path)

                    with zf.open(info, "r") as src, open(target_path, "wb") as dst:
                        while True:
                            chunk = src.read(65536)
                            if not chunk:
                                break
                            dst.write(chunk)

                    extracted_files.append(norm_posix)

        except Exception:
            for f in reversed(created_files):
                try:
                    if os.path.exists(f) and os.path.isfile(f):
                        os.remove(f)
                except OSError:
                    pass
            for d in reversed(created_dirs):
                try:
                    if os.path.exists(d) and os.path.isdir(d) and not os.listdir(d):
                        os.rmdir(d)
                except OSError:
                    pass
            raise

        return sorted(extracted_files)
