import fnmatch


def _matches_value(ctx_val, target_val) -> bool:
    if isinstance(ctx_val, bool) != isinstance(target_val, bool):
        return False
    return ctx_val == target_val


def _is_valid_request(request: dict) -> bool:
    if not isinstance(request, dict):
        return False

    required_keys = (
        "subject_id",
        "tenant_id",
        "resource_tenant_id",
        "roles",
        "action",
        "resource",
        "context",
    )
    for key in required_keys:
        if key not in request:
            return False

    subject_id = request["subject_id"]
    if not isinstance(subject_id, str) or not subject_id:
        return False

    tenant_id = request["tenant_id"]
    if not isinstance(tenant_id, str) or not tenant_id:
        return False

    resource_tenant_id = request["resource_tenant_id"]
    if not isinstance(resource_tenant_id, str) or not resource_tenant_id:
        return False

    roles = request["roles"]
    if not isinstance(roles, list) or len(roles) == 0:
        return False
    if not all(isinstance(r, str) and len(r) > 0 for r in roles):
        return False

    action = request["action"]
    if not isinstance(action, str) or not action:
        return False

    resource = request["resource"]
    if not isinstance(resource, str) or not resource:
        return False

    context = request["context"]
    if not isinstance(context, dict):
        return False

    return True


def _is_valid_policy(policy: dict) -> bool:
    if not isinstance(policy, dict):
        return False

    required_keys = ("effect", "tenant", "roles", "actions", "resources")
    for key in required_keys:
        if key not in policy:
            return False

    if policy["effect"] not in ("allow", "deny"):
        return False

    tenant = policy["tenant"]
    if not isinstance(tenant, str) or not tenant:
        return False

    roles = policy["roles"]
    if not isinstance(roles, list) or len(roles) == 0:
        return False
    if not all(isinstance(r, str) and len(r) > 0 for r in roles):
        return False

    actions = policy["actions"]
    if not isinstance(actions, list) or len(actions) == 0:
        return False
    if not all(isinstance(a, str) and len(a) > 0 for a in actions):
        return False

    resources = policy["resources"]
    if not isinstance(resources, list) or len(resources) == 0:
        return False
    if not all(isinstance(res, str) and len(res) > 0 for res in resources):
        return False

    if "conditions" in policy:
        conditions = policy["conditions"]
        if not isinstance(conditions, dict):
            return False
        if not all(isinstance(k, str) for k in conditions.keys()):
            return False

    return True


def authorize(request: dict, policies: list[dict]) -> bool:
    if not _is_valid_request(request):
        return False

    if request["tenant_id"] != request["resource_tenant_id"]:
        return False

    if not isinstance(policies, list):
        return False

    for policy in policies:
        if not _is_valid_policy(policy):
            return False

    has_allow = False
    req_roles = set(request["roles"])

    for policy in policies:
        if policy["tenant"] != "*" and policy["tenant"] != request["tenant_id"]:
            continue

        pol_roles = set(policy["roles"])
        if "*" not in pol_roles and "*" not in req_roles and not (req_roles & pol_roles):
            continue

        if not any(fnmatch.fnmatchcase(request["action"], pat) for pat in policy["actions"]):
            continue

        if not any(fnmatch.fnmatchcase(request["resource"], pat) for pat in policy["resources"]):
            continue

        conditions = policy.get("conditions")
        if conditions:
            context = request["context"]
            cond_matched = True
            for cond_key, cond_val in conditions.items():
                if cond_key not in context:
                    cond_matched = False
                    break
                ctx_val = context[cond_key]
                if isinstance(cond_val, list):
                    match = (
                        any(_matches_value(ctx_val, item) for item in cond_val)
                        or _matches_value(ctx_val, cond_val)
                        or (
                            isinstance(ctx_val, (list, tuple, set))
                            and any(any(_matches_value(ci, item) for item in cond_val) for ci in ctx_val)
                        )
                    )
                    if not match:
                        cond_matched = False
                        break
                else:
                    if not _matches_value(ctx_val, cond_val):
                        cond_matched = False
                        break
            if not cond_matched:
                continue

        if policy["effect"] == "deny":
            return False
        elif policy["effect"] == "allow":
            has_allow = True

    return has_allow
