import re
from decimal import Decimal
from typing import Dict, Optional


class _PaymentState:
    __slots__ = ("authorized", "captured", "refunded", "reversed", "next_sequence")

    def __init__(
        self,
        authorized: Decimal,
        captured: Decimal,
        refunded: Decimal,
        reversed: Decimal,
        next_sequence: int,
    ):
        self.authorized = authorized
        self.captured = captured
        self.refunded = refunded
        self.reversed = reversed
        self.next_sequence = next_sequence

    def clone(self) -> "_PaymentState":
        return _PaymentState(
            self.authorized,
            self.captured,
            self.refunded,
            self.reversed,
            self.next_sequence,
        )

    @property
    def available_to_capture(self) -> Decimal:
        return self.authorized - self.captured

    @property
    def merchant_balance(self) -> Decimal:
        return self.captured - self.refunded - self.reversed


class PaymentLedger:
    def __init__(self):
        self._events_by_id: Dict[str, dict] = {}
        self._payments: Dict[str, _PaymentState] = {}
        self._buffered: Dict[str, Dict[int, dict]] = {}

    def apply(self, event: dict) -> str:
        if not isinstance(event, dict):
            raise ValueError("Event must be a dict")

        required_keys = {"event_id", "payment_id", "sequence", "type", "amount"}
        if set(event.keys()) != required_keys:
            raise ValueError("Event must contain exactly the required fields")

        event_id = event["event_id"]
        if not isinstance(event_id, str) or not event_id:
            raise ValueError("event_id must be a non-empty string")

        payment_id = event["payment_id"]
        if not isinstance(payment_id, str) or not payment_id:
            raise ValueError("payment_id must be a non-empty string")

        sequence = event["sequence"]
        if type(sequence) is not int or sequence <= 0:
            raise ValueError("sequence must be a positive int")

        event_type = event["type"]
        if event_type not in {"authorized", "captured", "refunded", "reversed"}:
            raise ValueError(f"Invalid event type: {event_type}")

        amount_str = event["amount"]
        if not isinstance(amount_str, str):
            raise ValueError("amount must be a string")
        if not re.match(r"^\d+(\.\d{1,2})?$", amount_str):
            raise ValueError("amount must be a positive decimal string with at most two fractional digits")
        amount_dec = Decimal(amount_str)
        if amount_dec <= Decimal("0"):
            raise ValueError("amount must be positive")

        event_copy = {
            "event_id": event_id,
            "payment_id": payment_id,
            "sequence": sequence,
            "type": event_type,
            "amount": amount_str,
        }

        # Check identical duplicate or event_id content mismatch
        if event_id in self._events_by_id:
            existing = self._events_by_id[event_id]
            if existing == event_copy:
                return "duplicate"
            raise ValueError(f"Event ID '{event_id}' reused with different content")

        payment = self._payments.get(payment_id)
        expected_sequence = payment.next_sequence if payment is not None else 1

        # Check sequence reuse
        if sequence < expected_sequence:
            raise ValueError(f"Sequence {sequence} already applied for payment '{payment_id}'")

        buffered_for_payment = self._buffered.get(payment_id, {})
        if sequence in buffered_for_payment:
            raise ValueError(f"Sequence {sequence} already buffered for payment '{payment_id}'")

        # Future event -> buffer
        if sequence > expected_sequence:
            self._events_by_id[event_id] = event_copy
            if payment_id not in self._buffered:
                self._buffered[payment_id] = {}
            self._buffered[payment_id][sequence] = event_copy
            return "buffered"

        # Gap closes -> simulate applying incoming and consecutive buffered events atomically
        events_to_apply = [event_copy]
        curr_seq = sequence + 1
        while curr_seq in buffered_for_payment:
            events_to_apply.append(buffered_for_payment[curr_seq])
            curr_seq += 1

        simulated_payment = payment.clone() if payment is not None else None

        for evt in events_to_apply:
            evt_seq = evt["sequence"]
            evt_type = evt["type"]
            evt_amt = Decimal(evt["amount"])

            if evt_seq == 1:
                if evt_type != "authorized":
                    raise ValueError("Sequence 1 must authorize")
                simulated_payment = _PaymentState(
                    authorized=evt_amt,
                    captured=Decimal("0.00"),
                    refunded=Decimal("0.00"),
                    reversed=Decimal("0.00"),
                    next_sequence=2,
                )
            else:
                if simulated_payment is None:
                    raise ValueError("Payment must be authorized before subsequent events")
                if evt_type == "authorized":
                    raise ValueError("Sequence > 1 cannot authorize")
                elif evt_type == "captured":
                    if simulated_payment.captured + evt_amt > simulated_payment.authorized:
                        raise ValueError("Captures cannot exceed authorization")
                    simulated_payment.captured += evt_amt
                elif evt_type == "refunded":
                    remaining = (
                        simulated_payment.captured
                        - simulated_payment.refunded
                        - simulated_payment.reversed
                    )
                    if evt_amt > remaining:
                        raise ValueError(
                            "Refunds cannot exceed captured minus prior refunds and reversals"
                        )
                    simulated_payment.refunded += evt_amt
                elif evt_type == "reversed":
                    remaining = (
                        simulated_payment.captured
                        - simulated_payment.refunded
                        - simulated_payment.reversed
                    )
                    if evt_amt > remaining:
                        raise ValueError(
                            "Reversals follow the same remaining-settled limit"
                        )
                    simulated_payment.reversed += evt_amt
                simulated_payment.next_sequence += 1

        # Commit state updates atomically
        self._events_by_id[event_id] = event_copy
        for drained_evt in events_to_apply[1:]:
            del self._buffered[payment_id][drained_evt["sequence"]]

        if payment_id in self._buffered and not self._buffered[payment_id]:
            del self._buffered[payment_id]

        self._payments[payment_id] = simulated_payment
        return "applied"

    def state(self, payment_id) -> Optional[dict]:
        if payment_id not in self._payments:
            return None
        p = self._payments[payment_id]
        return {
            "authorized": f"{p.authorized:.2f}",
            "captured": f"{p.captured:.2f}",
            "refunded": f"{p.refunded:.2f}",
            "reversed": f"{p.reversed:.2f}",
            "available_to_capture": f"{p.available_to_capture:.2f}",
            "merchant_balance": f"{p.merchant_balance:.2f}",
            "next_sequence": p.next_sequence,
        }

    def snapshot(self) -> dict:
        return {
            pid: self.state(pid)
            for pid in sorted(self._payments.keys())
        }
