class RetryableError(Exception):
    pass


class FatalError(Exception):
    pass


class CrashError(Exception):
    pass


class SagaOrchestrator:
    def __init__(
        self,
        executor,
        compensator,
        max_retries: int = 2,
        journal: dict | None = None,
    ):
        self.executor = executor
        self.compensator = compensator
        self.max_retries = max_retries
        self.journal = {} if journal is None else journal

    def _validate_input(self, saga_id: str, steps: list[str]) -> None:
        if not isinstance(saga_id, str) or not saga_id:
            raise ValueError("saga_id must be a non-empty string")
        if not isinstance(steps, list) or not steps:
            raise ValueError("steps must be a non-empty list of unique non-empty strings")
        for step in steps:
            if not isinstance(step, str) or not step:
                raise ValueError("each step must be a non-empty string")
        if len(steps) != len(set(steps)):
            raise ValueError("steps must be unique")

        if saga_id in self.journal:
            entry = self.journal[saga_id]
            existing_plan = None
            if isinstance(entry, dict):
                existing_plan = entry.get("plan")
                if existing_plan is None:
                    existing_plan = entry.get("steps")
                if existing_plan is None and any(
                    s not in steps for s in entry.get("completed", [])
                ):
                    raise ValueError(f"Step plan for saga '{saga_id}' has changed")
            elif isinstance(entry, (list, tuple)):
                existing_plan = entry

            if existing_plan is not None and list(existing_plan) != steps:
                raise ValueError(f"Step plan for saga '{saga_id}' has changed")

    def _get_or_create_record(self, saga_id: str, steps: list[str]) -> dict:
        if saga_id not in self.journal:
            record = {
                "plan": list(steps),
                "steps": list(steps),
                "completed": [],
                "compensated": [],
                "status": "running",
                "state": "running",
            }
            self.journal[saga_id] = record
            return record

        record = self.journal[saga_id]
        if not isinstance(record, dict):
            completed_steps = list(record) if isinstance(record, (list, tuple)) else []
            record = {
                "plan": list(steps),
                "steps": list(steps),
                "completed": completed_steps,
                "compensated": [],
                "status": "running",
                "state": "running",
            }
            self.journal[saga_id] = record
        else:
            record.setdefault("plan", list(steps))
            record.setdefault("steps", list(steps))
            record.setdefault("completed", [])
            record.setdefault("compensated", [])
            record.setdefault("status", "running")
            record.setdefault("state", "running")
        return record

    def _compensate(self, saga_id: str) -> str:
        record = self.journal[saga_id]
        record["status"] = "compensating"
        record["state"] = "compensating"

        completed = record.get("completed", [])
        compensated_list = record.setdefault("compensated", [])
        compensated_set = set(compensated_list)

        for step in reversed(completed):
            if step not in compensated_set:
                try:
                    self.compensator(step)
                except CrashError:
                    raise
                compensated_list.append(step)
                compensated_set.add(step)

        record["status"] = "compensated"
        record["state"] = "compensated"
        return "compensated"

    def _execute(self, saga_id: str, steps: list[str]) -> str:
        self._validate_input(saga_id, steps)
        record = self._get_or_create_record(saga_id, steps)

        if record.get("status") in ("completed",) or record.get("state") in ("completed",):
            return "completed"

        if record.get("status") in ("compensated",) or record.get("state") in ("compensated",):
            return "compensated"

        if record.get("status") == "compensating" or record.get("state") == "compensating":
            return self._compensate(saga_id)

        completed_set = set(record.get("completed", []))

        for step in steps:
            if step in completed_set:
                continue

            retries = 0
            while True:
                try:
                    self.executor(step)
                    record["completed"].append(step)
                    completed_set.add(step)
                    break
                except CrashError:
                    raise
                except RetryableError:
                    if retries < self.max_retries:
                        retries += 1
                        continue
                    return self._compensate(saga_id)
                except FatalError:
                    return self._compensate(saga_id)
                except Exception:
                    return self._compensate(saga_id)

        record["status"] = "completed"
        record["state"] = "completed"
        return "completed"

    def run(self, saga_id: str, steps: list[str]) -> str:
        return self._execute(saga_id, steps)

    def recover(self, saga_id: str, steps: list[str]) -> str:
        return self._execute(saga_id, steps)
