import ast
from typing import Set


def prune_dead_code_and_imports(source_code: str) -> str:
    """Prunes unused imports and dead top-level private functions from source code using the AST."""
    tree = ast.parse(source_code)

    def get_referenced_names(node: ast.AST) -> Set[str]:
        names: Set[str] = set()
        for child in ast.walk(node):
            if isinstance(child, ast.Name):
                names.add(child.id)
            elif isinstance(child, (ast.Global, ast.Nonlocal)):
                names.update(child.names)
            elif isinstance(child, (ast.Assign, ast.AugAssign, ast.AnnAssign)):
                # If target is __all__, extract string constants as exported names
                is_all = False
                if isinstance(child, ast.Assign):
                    for t in child.targets:
                        if isinstance(t, ast.Name) and t.id == '__all__':
                            is_all = True
                elif isinstance(child, (ast.AugAssign, ast.AnnAssign)):
                    if isinstance(child.target, ast.Name) and child.target.id == '__all__':
                        is_all = True
                if is_all:
                    val_node = getattr(child, 'value', None)
                    if val_node is not None:
                        for c in ast.walk(val_node):
                            if isinstance(c, ast.Constant) and isinstance(c.value, str):
                                names.add(c.value)
            # Extract names from string type annotations (e.g., forward references)
            for attr in ('annotation', 'returns'):
                ann = getattr(child, attr, None)
                if isinstance(ann, ast.Constant) and isinstance(ann.value, str):
                    try:
                        sub = ast.parse(ann.value, mode='eval')
                        for sn in ast.walk(sub):
                            if isinstance(sn, ast.Name):
                                names.add(sn.id)
                    except Exception:
                        pass
        return names

    def fix_empty_bodies(root: ast.AST) -> None:
        for node in ast.walk(root):
            if isinstance(node, ast.Module):
                continue
            if hasattr(node, 'body') and isinstance(node.body, list) and len(node.body) == 0:
                node.body = [ast.Pass()]
            if isinstance(node, (ast.Try, getattr(ast, 'TryStar', ast.Try))):
                if not node.handlers and hasattr(node, 'finalbody') and len(node.finalbody) == 0:
                    node.finalbody = [ast.Pass()]

    # Separate top-level private functions from roots (and imports)
    top_private_funcs = []
    roots = []
    for stmt in tree.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith('_'):
            top_private_funcs.append(stmt)
        elif isinstance(stmt, (ast.Import, ast.ImportFrom)):
            pass
        else:
            roots.append(stmt)

    # Compute live names transitively from root statements
    live_names: Set[str] = set()
    for r in roots:
        live_names.update(get_referenced_names(r))

    live_funcs = set()
    changed = True
    while changed:
        changed = False
        for func_node in top_private_funcs:
            if func_node.name in live_names and func_node not in live_funcs:
                live_funcs.add(func_node)
                live_names.update(get_referenced_names(func_node))
                changed = True

    # Reconstruct top-level module body with live private functions and root statements
    new_body = []
    for stmt in tree.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith('_'):
            if stmt in live_funcs:
                new_body.append(stmt)
        else:
            new_body.append(stmt)
    tree.body = new_body

    # Prune unused imports across the AST
    class ImportPruner(ast.NodeTransformer):
        def visit_Import(self, node: ast.Import):
            node.names = [
                alias for alias in node.names
                if (alias.asname or alias.name.split('.')[0]) in live_names
            ]
            if not node.names:
                return None
            return node

        def visit_ImportFrom(self, node: ast.ImportFrom):
            node.names = [
                alias for alias in node.names
                if alias.name == '*' or (alias.asname or alias.name) in live_names
            ]
            if not node.names:
                return None
            return node

    tree = ImportPruner().visit(tree)
    fix_empty_bodies(tree)
    ast.fix_missing_locations(tree)
    return ast.unparse(tree)
