import os
import pathlib
import re
import stat
import unicodedata
import zipfile


def safe_extract_zip(
    archive_path: str,
    destination: str,
    max_files: int = 1000,
    max_uncompressed_bytes: int = 10000000,
    max_compression_ratio: float = 100.0,
) -> list[str]:
    dest_abs = os.path.abspath(destination)

    entries_to_extract = []
    seen_all_entries = set()
    seen_files = set()
    seen_dirs = set()

    file_count = 0
    cumulative_uncompressed_bytes = 0

    # Phase 1: Validate entire archive in-memory before writing anything
    with zipfile.ZipFile(archive_path, "r") as zf:
        infolist = zf.infolist()

        for info in infolist:
            raw_name = getattr(info, "orig_filename", None) or info.filename

            # Check NUL byte
            if "\x00" in raw_name or "\x00" in info.filename:
                raise ValueError(f"Entry contains NUL byte: {raw_name!r}")

            # Check Unix symlink
            mode = info.external_attr >> 16
            if mode != 0 and stat.S_ISLNK(mode):
                raise ValueError(f"Entry is a Unix symlink: {raw_name!r}")

            # Check absolute paths (POSIX / Windows drive specifications)
            if raw_name.startswith(("/", "\\")) or info.filename.startswith(("/", "\\")):
                raise ValueError(f"Entry is absolute: {raw_name!r}")
            if re.match(r"^[a-zA-Z]:", raw_name) or re.match(r"^[a-zA-Z]:", info.filename):
                raise ValueError(f"Entry contains a drive specification: {raw_name!r}")

            win_path = pathlib.PureWindowsPath(raw_name)
            posix_path = pathlib.PurePosixPath(raw_name)
            if win_path.is_absolute() or posix_path.is_absolute() or win_path.drive:
                raise ValueError(f"Entry is absolute: {raw_name!r}")

            # Determine if entry is a directory
            is_dir = (
                info.is_dir()
                or raw_name.endswith(("/", "\\"))
                or info.filename.endswith(("/", "\\"))
                or (mode != 0 and stat.S_ISDIR(mode))
            )

            # Unicode NFC normalization & directory traversal (..) check across slash styles
            nfc_raw = unicodedata.normalize("NFC", raw_name)
            clean_name = nfc_raw.replace("\\", "/")
            parts = clean_name.split("/")

            stack = []
            for part in parts:
                if part == "" or part == ".":
                    continue
                elif part == "..":
                    if not stack:
                        raise ValueError(f"Entry escapes destination via '..': {raw_name!r}")
                    stack.pop()
                else:
                    stack.append(part)

            if not stack:
                raise ValueError(f"Entry resolves to root or empty path: {raw_name!r}")

            posix_rel_path = "/".join(stack)
            nfc_posix_path = unicodedata.normalize("NFC", posix_rel_path)

            # Destination containment check
            target_abs = os.path.abspath(os.path.join(dest_abs, *stack))
            try:
                common = os.path.commonpath([dest_abs, target_abs])
            except ValueError:
                raise ValueError(f"Entry escapes destination directory: {raw_name!r}")

            if common != dest_abs or target_abs == dest_abs:
                raise ValueError(f"Entry escapes destination directory: {raw_name!r}")

            # Unicode NFC normalization collision check
            if nfc_posix_path in seen_all_entries:
                raise ValueError(
                    f"Name collision after Unicode NFC normalization: {nfc_posix_path!r}"
                )
            seen_all_entries.add(nfc_posix_path)

            if is_dir:
                if nfc_posix_path in seen_files:
                    raise ValueError(f"Directory collides with file entry: {nfc_posix_path!r}")
                for k in range(1, len(stack)):
                    prefix = "/".join(stack[:k])
                    if prefix in seen_files:
                        raise ValueError(
                            f"Directory parent path collides with file entry: {prefix!r}"
                        )
                seen_dirs.add(nfc_posix_path)
            else:
                if nfc_posix_path in seen_dirs:
                    raise ValueError(f"File collides with directory entry: {nfc_posix_path!r}")
                for k in range(1, len(stack)):
                    prefix = "/".join(stack[:k])
                    if prefix in seen_files:
                        raise ValueError(
                            f"File parent path collides with file entry: {prefix!r}"
                        )
                seen_files.add(nfc_posix_path)

            # Cumulative uncompressed size check
            cumulative_uncompressed_bytes += info.file_size
            if cumulative_uncompressed_bytes > max_uncompressed_bytes:
                raise ValueError(
                    f"Cumulative uncompressed size ({cumulative_uncompressed_bytes} bytes) "
                    f"exceeds limit ({max_uncompressed_bytes} bytes)"
                )

            # File count and per-file compression ratio check (directory entries do not count)
            if not is_dir:
                file_count += 1
                if file_count > max_files:
                    raise ValueError(f"File count ({file_count}) exceeds limit ({max_files})")

                if info.file_size < 0 or info.compress_size < 0:
                    raise ValueError(f"Invalid file size or compressed size: {raw_name!r}")

                if info.file_size > 0:
                    if info.compress_size <= 0:
                        raise ValueError(
                            f"Per-file compression ratio limit exceeded for {raw_name!r}"
                        )
                    ratio = info.file_size / info.compress_size
                    if ratio > max_compression_ratio:
                        raise ValueError(
                            f"Per-file compression ratio limit exceeded for {raw_name!r}: "
                            f"{ratio} > {max_compression_ratio}"
                        )

            entries_to_extract.append((info, is_dir, nfc_posix_path, target_abs))

        # Phase 2: Extraction beneath destination
        os.makedirs(dest_abs, exist_ok=True)
        extracted_file_paths = []

        for info, is_dir, nfc_posix_path, target_abs in entries_to_extract:
            if is_dir:
                os.makedirs(target_abs, exist_ok=True)
            else:
                parent_dir = os.path.dirname(target_abs)
                os.makedirs(parent_dir, exist_ok=True)

                with zf.open(info, "r") as src, open(target_abs, "wb") as dst:
                    while chunk := src.read(65536):
                        dst.write(chunk)

                extracted_file_paths.append(nfc_posix_path)

        return sorted(extracted_file_paths)
