import fnmatch


def authorize(request: dict, policies: list[dict]) -> bool:
    if not isinstance(request, dict):
        return False

    # Validate request fields
    subject_id = request.get("subject_id")
    if not isinstance(subject_id, str) or not subject_id:
        return False

    tenant_id = request.get("tenant_id")
    if not isinstance(tenant_id, str) or not tenant_id:
        return False

    resource_tenant_id = request.get("resource_tenant_id")
    if not isinstance(resource_tenant_id, str) or not resource_tenant_id:
        return False

    roles = request.get("roles")
    if (
        not isinstance(roles, list)
        or len(roles) == 0
        or not all(isinstance(r, str) and r for r in roles)
    ):
        return False

    action = request.get("action")
    if not isinstance(action, str) or not action:
        return False

    resource = request.get("resource")
    if not isinstance(resource, str) or not resource:
        return False

    context = request.get("context")
    if not isinstance(context, dict):
        return False

    # Enforce tenant isolation
    if tenant_id != resource_tenant_id:
        return False

    # Validate policies
    if not isinstance(policies, list):
        return False

    for p in policies:
        if not isinstance(p, dict):
            return False

        if p.get("effect") not in ("allow", "deny"):
            return False

        p_tenant = p.get("tenant")
        if not isinstance(p_tenant, str) or not p_tenant:
            return False

        p_roles = p.get("roles")
        if (
            not isinstance(p_roles, list)
            or len(p_roles) == 0
            or not all(isinstance(r, str) and r for r in p_roles)
        ):
            return False

        p_actions = p.get("actions")
        if (
            not isinstance(p_actions, list)
            or len(p_actions) == 0
            or not all(isinstance(a, str) and a for a in p_actions)
        ):
            return False

        p_resources = p.get("resources")
        if (
            not isinstance(p_resources, list)
            or len(p_resources) == 0
            or not all(isinstance(res, str) and res for res in p_resources)
        ):
            return False

        if "conditions" in p:
            if not isinstance(p["conditions"], dict):
                return False

    # Policy evaluation
    allowed = False
    for p in policies:
        # Tenant matching
        if p["tenant"] != "*" and p["tenant"] != tenant_id:
            continue

        # Role matching (* allowed)
        if (
            "*" not in p["roles"]
            and "*" not in roles
            and not (set(p["roles"]) & set(roles))
        ):
            continue

        # Action matching (case-sensitive fnmatch)
        if not any(fnmatch.fnmatchcase(action, pat) for pat in p["actions"]):
            continue

        # Resource matching (case-sensitive fnmatch)
        if not any(
            fnmatch.fnmatchcase(resource, pat) for pat in p["resources"]
        ):
            continue

        # Conditions matching
        conditions = p.get("conditions")
        if conditions is not None:
            cond_match = True
            for k, v in conditions.items():
                if k not in context:
                    cond_match = False
                    break
                ctx_val = context[k]
                if isinstance(v, list):
                    if ctx_val not in v:
                        cond_match = False
                        break
                else:
                    if ctx_val != v:
                        cond_match = False
                        break
            if not cond_match:
                continue

        # Check effect
        if p["effect"] == "deny":
            return False
        elif p["effect"] == "allow":
            allowed = True

    return allowed
