from decimal import Decimal
import re


class PaymentLedger:
    def __init__(self) -> None:
        self._events_by_id: dict[str, dict] = {}
        self._payments: dict[str, dict] = {}
        self._payment_history: dict[str, dict[int, dict]] = {}
        self._payment_buffered: dict[str, dict[int, dict]] = {}

    def apply(self, event: dict) -> str:
        if not isinstance(event, dict):
            raise ValueError("Event must be a dictionary")
        if set(event.keys()) != {"event_id", "payment_id", "sequence", "type", "amount"}:
            raise ValueError("Event must contain exactly the required fields")

        event_id = event["event_id"]
        payment_id = event["payment_id"]
        sequence = event["sequence"]
        event_type = event["type"]
        amount_str = event["amount"]

        if not isinstance(event_id, str) or not event_id:
            raise ValueError("event_id must be a non-empty string")
        if not isinstance(payment_id, str) or not payment_id:
            raise ValueError("payment_id must be a non-empty string")
        if type(sequence) is not int or sequence <= 0:
            raise ValueError("sequence must be a positive integer")
        if not isinstance(event_type, str) or event_type not in {"authorized", "captured", "refunded", "reversed"}:
            raise ValueError("type must be authorized, captured, refunded, or reversed")
        if sequence == 1 and event_type != "authorized":
            raise ValueError("Sequence 1 must authorize")
        if sequence > 1 and event_type == "authorized":
            raise ValueError("Cannot authorize after sequence 1")

        if not isinstance(amount_str, str) or not re.match(r"^(?:0|[1-9]\d*)(\.\d{1,2})?$", amount_str):
            raise ValueError("amount must be a positive decimal string with at most two fractional digits")
        amt = Decimal(amount_str)
        if amt <= Decimal("0"):
            raise ValueError("amount must be positive")

        # Check existing event_id
        if event_id in self._events_by_id:
            existing = self._events_by_id[event_id]
            if existing == event:
                return "duplicate"
            raise ValueError("Reusing event_id with different content")

        # Check sequence reuse for this payment_id
        if payment_id in self._payment_history and sequence in self._payment_history[payment_id]:
            raise ValueError("Reusing sequence with different content (already applied)")
        if payment_id in self._payment_buffered and sequence in self._payment_buffered[payment_id]:
            raise ValueError("Reusing sequence with different content (already buffered)")

        # Determine current expected sequence
        expected_seq = self._payments[payment_id]["next_sequence"] if payment_id in self._payments else 1

        if sequence < expected_seq:
            raise ValueError("Reusing past sequence with different content")

        if sequence > expected_seq:
            # Future event -> buffer
            if payment_id not in self._payment_buffered:
                self._payment_buffered[payment_id] = {}
            event_copy = dict(event)
            self._payment_buffered[payment_id][sequence] = event_copy
            self._events_by_id[event_id] = event_copy
            return "buffered"

        # sequence == expected_seq: drain consecutive
        buffered_events = self._payment_buffered.get(payment_id, {})
        chain = [dict(event)]
        s = sequence + 1
        while s in buffered_events:
            chain.append(buffered_events[s])
            s += 1

        # Simulate atomic application
        cur = self._payments.get(payment_id)
        if cur is not None:
            sim_auth = cur["authorized"]
            sim_cap = cur["captured"]
            sim_ref = cur["refunded"]
            sim_rev = cur["reversed"]
            sim_seq = cur["next_sequence"]
        else:
            sim_auth = Decimal("0")
            sim_cap = Decimal("0")
            sim_ref = Decimal("0")
            sim_rev = Decimal("0")
            sim_seq = 1

        for ev in chain:
            ev_type = ev["type"]
            ev_amt = Decimal(ev["amount"])

            if ev["sequence"] == 1:
                if ev_type != "authorized":
                    raise ValueError("Sequence 1 must authorize")
                sim_auth = ev_amt
            else:
                if ev_type == "authorized":
                    raise ValueError("Cannot authorize after sequence 1")
                elif ev_type == "captured":
                    if sim_cap + ev_amt > sim_auth:
                        raise ValueError("Captures cannot exceed authorization")
                    sim_cap += ev_amt
                elif ev_type == "refunded":
                    remaining = sim_cap - sim_ref - sim_rev
                    if ev_amt > remaining:
                        raise ValueError("Refunds cannot exceed captured minus prior refunds and reversals")
                    sim_ref += ev_amt
                elif ev_type == "reversed":
                    remaining = sim_cap - sim_ref - sim_rev
                    if ev_amt > remaining:
                        raise ValueError("Reversals cannot exceed captured minus prior refunds and reversals")
                    sim_rev += ev_amt
                else:
                    raise ValueError(f"Invalid type {ev_type}")
            sim_seq += 1

        # Commit state atomically
        self._events_by_id[event_id] = dict(event)
        if payment_id not in self._payment_history:
            self._payment_history[payment_id] = {}

        for ev in chain:
            self._payment_history[payment_id][ev["sequence"]] = ev
            if payment_id in self._payment_buffered and ev["sequence"] in self._payment_buffered[payment_id]:
                del self._payment_buffered[payment_id][ev["sequence"]]

        self._payments[payment_id] = {
            "authorized": sim_auth,
            "captured": sim_cap,
            "refunded": sim_ref,
            "reversed": sim_rev,
            "next_sequence": sim_seq,
        }
        return "applied"

    def state(self, payment_id: str) -> dict | None:
        if payment_id not in self._payments:
            return None
        p = self._payments[payment_id]
        auth = p["authorized"]
        cap = p["captured"]
        ref = p["refunded"]
        rev = p["reversed"]
        avail = auth - cap
        balance = cap - ref - rev
        return {
            "authorized": f"{auth:.2f}",
            "captured": f"{cap:.2f}",
            "refunded": f"{ref:.2f}",
            "reversed": f"{rev:.2f}",
            "available_to_capture": f"{avail:.2f}",
            "merchant_balance": f"{balance:.2f}",
            "next_sequence": p["next_sequence"],
        }

    def snapshot(self) -> dict:
        return {pid: self.state(pid) for pid in sorted(self._payments.keys())}
