class RetryableError(Exception):
    pass


class FatalError(Exception):
    pass


class CrashError(Exception):
    pass


class SagaOrchestrator:
    def __init__(
        self,
        executor,
        compensator,
        max_retries: int = 2,
        journal: dict | None = None,
    ):
        self.executor = executor
        self.compensator = compensator
        self.max_retries = max_retries
        if journal is None:
            self.journal = {}
        else:
            self.journal = journal

    def _validate(self, saga_id: str, steps: list[str]) -> None:
        if not isinstance(saga_id, str):
            raise TypeError("saga_id must be a string")
        if not saga_id:
            raise ValueError("saga_id must be a non-empty string")
        if not isinstance(steps, list):
            raise TypeError("steps must be a list of strings")
        for step in steps:
            if not isinstance(step, str):
                raise TypeError("Steps must be strings")
            if not step:
                raise ValueError("Steps must be non-empty strings")
        if len(steps) != len(set(steps)):
            raise ValueError("Steps must be unique")
        if saga_id in self.journal:
            record = self.journal[saga_id]
            if isinstance(record, dict) and "steps" in record:
                if record["steps"] != steps:
                    raise ValueError(f"Changed step plan for existing saga '{saga_id}'")

    def _execute_step(self, callback, step: str) -> None:
        attempts = 0
        while True:
            try:
                callback(step)
                return
            except CrashError:
                raise
            except RetryableError:
                attempts += 1
                if attempts > self.max_retries:
                    raise FatalError(f"Retries exhausted for step '{step}'")
            except FatalError:
                raise
            except Exception as e:
                raise FatalError(f"Unexpected callback error: {e}") from e

    def _compensate(self, saga_id: str, record: dict) -> str:
        record["status"] = "compensating"
        completed = record["completed"]
        compensated = record["compensated"]

        for step in reversed(completed):
            if step in compensated:
                continue
            attempts = 0
            while True:
                try:
                    self.compensator(step)
                    compensated.append(step)
                    break
                except CrashError:
                    raise
                except RetryableError:
                    attempts += 1
                    if attempts > self.max_retries:
                        raise
                except Exception:
                    raise

        record["status"] = "compensated"
        return "compensated"

    def run(self, saga_id: str, steps: list[str]) -> str:
        self._validate(saga_id, steps)
        if saga_id not in self.journal:
            self.journal[saga_id] = {
                "steps": list(steps),
                "completed": [],
                "compensated": [],
                "status": "running",
            }

        record = self.journal[saga_id]
        if record.get("status") == "completed":
            return "completed"
        if record.get("status") == "compensated":
            return "compensated"
        if record.get("status") == "compensating":
            return self._compensate(saga_id, record)

        for step in steps:
            if step in record["completed"]:
                continue
            try:
                self._execute_step(self.executor, step)
                record["completed"].append(step)
            except CrashError:
                raise
            except FatalError:
                return self._compensate(saga_id, record)

        record["status"] = "completed"
        return "completed"

    def recover(self, saga_id: str, steps: list[str]) -> str:
        return self.run(saga_id, steps)
