import re


def is_safe_sql_query(query: str) -> tuple[bool, str]:
    """Validates whether a SQL query or input fragment is safe from SQL injection attacks.

    Requirements addressed:
    1. Rejects malicious signatures:
       - Boolean/Tautology injection (e.g., "' OR '1'='1'", '" OR 1=1 --', "admin'--")
       - Stacked query execution (e.g., "; DROP TABLE", "; EXEC xp_cmdshell", "; DELETE FROM")
       - UNION-based data exfiltration (e.g., "UNION SELECT", "UNION ALL SELECT")
       - Time-based blind execution (e.g., "pg_sleep(", "WAITFOR DELAY", "BENCHMARK(")
       - Obfuscation / inline comment evasion (e.g., "/*!50000SELECT*/", "UN/**/ION")
    2. Allows legitimate queries, including JSON operators, window functions, and SQL keywords inside strings.
    3. Handles case-insensitivity and normalized whitespace.

    Returns:
        tuple[bool, str]: (True, "SAFE") if valid and safe, or (False, "REASON") if malicious/unsafe.
    """
    if not isinstance(query, str):
        return False, "Invalid query format: query must be a string"

    # 1. Null byte and control character injection checks
    if "\x00" in query or "%00" in query or "\\0" in query:
        return False, "Obfuscation detected: Null byte injection"

    raw_stripped = query.strip()
    if not raw_stripped:
        return True, "SAFE"

    # 2. Obfuscation checks: MySQL conditional/executable comments (e.g., /*!50000SELECT*/, /*!UNION*/)
    if re.search(r"/\*!\s*\d*", query, re.IGNORECASE):
        return (
            False,
            "Obfuscation detected: MySQL conditional/executable comment",
        )

    # 3. Obfuscation checks: Inline comment splitting keyword evasion (e.g., UN/**/ION, SEL/*foo*/ECT, O/**/R)
    if re.search(r"[a-zA-Z0-9_]\s*/\*.*?\*/\s*[a-zA-Z0-9_]", query, re.DOTALL):
        return False, "Obfuscation detected: Inline comment splitting keyword"

    # Normalize block comments to whitespace for secondary payload inspection
    normalized_comments_query = re.sub(r"/\*[\s\S]*?\*/", " ", query)

    # 4. Check for quote breakout truncation payloads (e.g., admin'--, admin' #, admin'/*, ' OR 1=1 --)
    if re.search(r"""['"]\s*(--|#|/\*)""", query) or re.search(
        r"""['"]\s*(--|#|/\*)""", normalized_comments_query
    ):
        return (
            False,
            "Malicious SQL injection detected: Quote breakout with comment"
            " truncation",
        )

    # 5. Raw standalone injection signatures and tautology breakouts
    raw_breakout_patterns = [
        # Boolean / Tautology breakouts
        (
            r"""^['"]\s*(OR|AND)\b""",
            "Boolean injection breakout at start of query",
        ),
        (
            r"""\)?\s*['"]\s*(OR|AND)\s+\(?\s*['"]?([a-zA-Z0-9_-]+)['"]?\s*=\s*['"]?\2['"]?""",
            "Boolean injection breakout with comparison tautology",
        ),
        (
            r"""\b\w+['"]\s*(OR|AND)\s+['"]?([a-zA-Z0-9_-]+)['"]?\s*=\s*['"]?\2['"]?""",
            "Boolean injection breakout after identifier with comparison"
            " tautology",
        ),
        (
            r"""\b\w+['"]\s*(OR|AND)\s+\d+\s*=\s*\d+""",
            "Boolean injection breakout after identifier with numeric"
            " tautology",
        ),
        (
            r"""\b\w+['"]\s*(OR|AND)\s+true\b""",
            "Boolean injection breakout with true",
        ),
        (
            r"""\b(OR|AND)\s+['"]?([a-zA-Z0-9_-]+)['"]?\s*=\s*['"]?\2['"]?""",
            "Boolean tautology expression",
        ),
        (
            r"""\b(OR|AND)\s+['"]{1,2}\s*=\s*['"]{1,2}""",
            "Empty string boolean tautology",
        ),
        (r"""\b(OR|AND)\s+true\b""", "Boolean tautology (OR true)"),
        (r"""\b(OR|AND)\s+1\s*=\s*1\b""", "Boolean tautology (1=1)"),
        (r"""\b(OR|AND)\s+0\s*=\s*0\b""", "Boolean tautology (0=0)"),
        (r"""\bHAVING\s+1\s*=\s*1\b""", "HAVING clause tautology"),
        (
            r"""['"]\s*(OR|AND)\s+['"]\s*=\s*['"]""",
            "Tautological boolean quote comparison",
        ),
        (
            r"""['"]\s*=\s*['"]\s*(OR|AND)\b""",
            "Quote equality followed by boolean operator",
        ),
        # Raw stacked query execution start
        (
            r"""^;\s*(DROP|EXEC|EXECUTE|DELETE|UPDATE|INSERT|SELECT|TRUNCATE|ALTER|CREATE|SHUTDOWN|GRANT|REVOKE)\b""",
            "Stacked query execution",
        ),
        # Raw UNION injection at start
        (
            r"""^['"]?\s*UNION\s+(ALL|DISTINCT)?\s*(\(\s*)?SELECT\b""",
            "UNION-based data exfiltration",
        ),
        # Standalone time-based functions at start
        (
            r"""^\s*pg_sleep\s*\(""",
            "Time-based blind execution (pg_sleep)",
        ),
        (
            r"""^\s*WAITFOR\s+(DELAY|TIME)\b""",
            "Time-based blind execution (WAITFOR)",
        ),
        (
            r"""^\s*BENCHMARK\s*\(""",
            "Time-based blind execution (BENCHMARK)",
        ),
        (r"""^\s*sleep\s*\(""", "Time-based blind execution (sleep)"),
    ]

    for pattern, reason in raw_breakout_patterns:
        if re.search(pattern, normalized_comments_query, re.IGNORECASE):
            return False, f"Malicious SQL injection detected: {reason}"

    # 6. Parse SQL structure into code tokens vs string literals & comments
    i = 0
    n = len(query)
    code_parts = []
    string_literals = []
    comments = []
    has_unclosed_string = False
    has_unclosed_comment = False

    while i < n:
        ch = query[i]

        # Single-quote string literal ('...')
        if ch == "'":
            i += 1
            str_val = []
            closed = False
            while i < n:
                if query[i] == "'":
                    if i + 1 < n and query[i + 1] == "'":
                        str_val.append("'")
                        i += 2
                    else:
                        closed = True
                        i += 1
                        break
                elif query[i] == "\\":
                    if i + 1 < n:
                        str_val.append(query[i + 1])
                        i += 2
                    else:
                        str_val.append(query[i])
                        i += 1
                else:
                    str_val.append(query[i])
                    i += 1
            if not closed:
                has_unclosed_string = True
            val = "".join(str_val)
            string_literals.append(val)
            code_parts.append(f" 'STR_{len(string_literals)-1}' ")
            continue

        # PostgreSQL dollar-quoted string ($$...$$ or $tag$...$tag$)
        if ch == "$":
            tag_match = re.match(r"^\$([a-zA-Z0-9_]*)\$", query[i:])
            if tag_match:
                tag = tag_match.group(0)
                end_idx = query.find(tag, i + len(tag))
                if end_idx != -1:
                    val = query[i + len(tag) : end_idx]
                    string_literals.append(val)
                    code_parts.append(f" 'STR_{len(string_literals)-1}' ")
                    i = end_idx + len(tag)
                    continue
                else:
                    has_unclosed_string = True
                    val = query[i + len(tag) :]
                    string_literals.append(val)
                    code_parts.append(f" 'STR_{len(string_literals)-1}' ")
                    break

        # Double-quoted identifier or string ("...")
        if ch == '"':
            i += 1
            str_val = []
            closed = False
            while i < n:
                if query[i] == '"':
                    if i + 1 < n and query[i + 1] == '"':
                        str_val.append('"')
                        i += 2
                    else:
                        closed = True
                        i += 1
                        break
                elif query[i] == "\\":
                    if i + 1 < n:
                        str_val.append(query[i + 1])
                        i += 2
                    else:
                        str_val.append(query[i])
                        i += 1
                else:
                    str_val.append(query[i])
                    i += 1
            if not closed:
                has_unclosed_string = True
            val = "".join(str_val)
            string_literals.append(val)
            code_parts.append(f' "STR_{len(string_literals)-1}" ')
            continue

        # Block comment (/* ... */)
        if ch == "/" and i + 1 < n and query[i + 1] == "*":
            end_idx = query.find("*/", i + 2)
            if end_idx != -1:
                comments.append(query[i : end_idx + 2])
                code_parts.append(" ")
                i = end_idx + 2
                continue
            else:
                has_unclosed_comment = True
                comments.append(query[i:])
                break

        # Line comment (-- ...)
        if ch == "-" and i + 1 < n and query[i + 1] == "-":
            end_idx = query.find("\n", i + 2)
            if end_idx != -1:
                comments.append(query[i:end_idx])
                code_parts.append(" ")
                i = end_idx + 1
            else:
                comments.append(query[i:])
                code_parts.append(" ")
                break
            continue

        # MySQL line comment (# ...) while preserving PostgreSQL JSON operators (#> and #>>)
        if ch == "#":
            if i + 1 < n and query[i + 1] in (">", "#"):
                code_parts.append(ch)
                i += 1
                continue
            end_idx = query.find("\n", i + 1)
            if end_idx != -1:
                comments.append(query[i:end_idx])
                code_parts.append(" ")
                i = end_idx + 1
            else:
                comments.append(query[i:])
                code_parts.append(" ")
                break
            continue

        code_parts.append(ch)
        i += 1

    # Unclosed strings or comments indicate syntax breakouts or injection truncation
    if has_unclosed_string:
        return (
            False,
            "Malicious SQL injection detected: Unclosed string literal / syntax"
            " breakout",
        )

    if has_unclosed_comment:
        return (
            False,
            "Malicious SQL injection detected: Unclosed comment / comment"
            " truncation",
        )

    if comments:
        return (
            False,
            "Malicious SQL injection detected: Comment syntax outside string"
            " literals",
        )

    # Inspect string literals for internal boolean breakout structures
    for s in string_literals:
        s_upper = s.strip().upper()
        if re.search(r"^\)?\s*(OR|AND)\s+\(?", s_upper):
            return (
                False,
                "Malicious SQL injection detected: Boolean breakout inside"
                " parsed string",
            )

    code_str = "".join(code_parts)
    normalized_code = " ".join(code_str.split())

    # 7. Stacked query execution detection (e.g., ; DROP TABLE, ; EXEC xp_cmdshell, ; DELETE FROM)
    clean_code_semi = normalized_code.rstrip("; ")
    if ";" in clean_code_semi:
        stacked_patterns = r";\s*(DROP|EXEC|EXECUTE|DELETE|UPDATE|INSERT|SELECT|TRUNCATE|ALTER|CREATE|SHUTDOWN|GRANT|REVOKE|CALL|DO|MERGE|DECLARE|XP_|SP_)\b"
        if re.search(stacked_patterns, clean_code_semi, re.IGNORECASE):
            return (
                False,
                "Malicious SQL injection detected: Stacked query execution",
            )
        return (
            False,
            "Malicious SQL injection detected: Multiple / stacked query"
            " execution",
        )

    if normalized_code.startswith(";"):
        return False, "Malicious SQL injection detected: Stacked query execution"

    # 8. UNION-based data exfiltration (e.g., UNION SELECT, UNION ALL SELECT, UNION(SELECT))
    union_pattern = r"\bUNION\b\s*(ALL|DISTINCT)?\s*(\(\s*)?SELECT\b"
    if re.search(union_pattern, normalized_code, re.IGNORECASE):
        return (
            False,
            "Malicious SQL injection detected: UNION-based data exfiltration",
        )

    # 9. Time-based blind execution (e.g., pg_sleep(, WAITFOR DELAY, BENCHMARK(, sleep()
    time_patterns = [
        r"\bpg_sleep\s*\(",
        r"\bsleep\s*\(",
        r"\bWAITFOR\s+(DELAY|TIME)\b",
        r"\bBENCHMARK\s*\(",
        r"\bdbms_pipe\s*\.\s*receive_message\b",
        r"\bdbms_lock\s*\.\s*sleep\b",
    ]
    for tp in time_patterns:
        if re.search(tp, normalized_code, re.IGNORECASE):
            return (
                False,
                "Malicious SQL injection detected: Time-based blind execution",
            )

    # 10. Boolean / Tautology injection in parsed SQL structure
    tautology_patterns = [
        r"\b(OR|AND|HAVING|WHERE)\b\s+(\d+)\s*=\s*\2\b",
        r"\b(OR|AND|HAVING|WHERE)\b\s+true\b",
        r"\b(OR|AND|HAVING|WHERE)\b\s+1\s*=\s*1\b",
        r"\b(OR|AND|HAVING|WHERE)\b\s+0\s*=\s*0\b",
        r"\b(OR|AND|HAVING|WHERE)\b\s*\(\s*(\d+)\s*=\s*\2\s*\)",
        r"\b(OR|AND|HAVING|WHERE)\b\s*\(\s*1\s*=\s*1\s*\)",
        r"^\s*(\d+)\s*=\s*\1\s*$",
        r"^\s*(\d+)\s+(OR|AND)\s+\1\s*=\s*\1",
    ]
    for bp in tautology_patterns:
        if re.search(bp, normalized_code, re.IGNORECASE):
            return (
                False,
                "Malicious SQL injection detected: Boolean/Tautology injection",
            )

    # Check for string literal equality tautologies ('STR_x' = 'STR_y' where literal content matches)
    str_eq_matches = re.finditer(
        r"""\b(OR|AND|HAVING|WHERE)\b\s*\(?\s*['"]STR_(\d+)['"]\s*=\s*['"]STR_(\d+)['"]\s*\)?""",
        normalized_code,
        re.IGNORECASE,
    )
    for match in str_eq_matches:
        idx1 = int(match.group(2))
        idx2 = int(match.group(3))
        if idx1 < len(string_literals) and idx2 < len(string_literals):
            if string_literals[idx1] == string_literals[idx2]:
                return (
                    False,
                    "Malicious SQL injection detected: Boolean/Tautology string"
                    " comparison",
                )

    str_eq_standalone = re.finditer(
        r"""(?:WHERE|HAVING|^)\s*\(?\s*['"]STR_(\d+)['"]\s*=\s*['"]STR_(\d+)['"]\s*\)?""",
        normalized_code,
        re.IGNORECASE,
    )
    for match in str_eq_standalone:
        idx1 = int(match.group(1))
        idx2 = int(match.group(2))
        if idx1 < len(string_literals) and idx2 < len(string_literals):
            if string_literals[idx1] == string_literals[idx2]:
                return (
                    False,
                    "Malicious SQL injection detected: Constant string"
                    " tautology",
                )

    if re.search(r"^\s*(OR|AND)\b", normalized_code, re.IGNORECASE):
        return (
            False,
            "Malicious SQL injection detected: Injected boolean condition",
        )

    return True, "SAFE"
