import collections
import threading
import time
from typing import Any, Optional


class TimeBoundedLRUCache:
    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        if capacity <= 0:
            raise ValueError("Capacity must be greater than 0")
        self.capacity = capacity
        self.default_ttl_seconds = default_ttl_seconds
        self.cache: collections.OrderedDict[str, tuple[Any, float]] = collections.OrderedDict()
        self.lock = threading.RLock()

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        if ttl is None:
            ttl = self.default_ttl_seconds

        with self.lock:
            expiry = time.monotonic() + ttl
            if key in self.cache:
                self.cache[key] = (value, expiry)
                self.cache.move_to_end(key)
                return

            while len(self.cache) >= self.capacity:
                now = time.monotonic()
                expired_keys = [k for k, (_, exp) in self.cache.items() if exp <= now]
                if expired_keys:
                    oldest_expired = min(expired_keys, key=lambda k: self.cache[k][1])
                    del self.cache[oldest_expired]
                else:
                    self.cache.popitem(last=False)

            self.cache[key] = (value, expiry)

    def get(self, key: str) -> Optional[Any]:
        with self.lock:
            if key not in self.cache:
                return None
            value, expiry = self.cache[key]
            if time.monotonic() >= expiry:
                del self.cache[key]
                return None
            self.cache.move_to_end(key)
            return value

    def delete(self, key: str) -> bool:
        with self.lock:
            if key in self.cache:
                del self.cache[key]
                return True
            return False

    def cleanup_expired(self) -> int:
        with self.lock:
            now = time.monotonic()
            expired_keys = [k for k, (_, exp) in self.cache.items() if exp <= now]
            for k in expired_keys:
                del self.cache[k]
            return len(expired_keys)

    def size(self) -> int:
        with self.lock:
            now = time.monotonic()
            return sum(1 for _, exp in self.cache.values() if exp > now)
