import bisect
import threading
import time
from typing import Dict, List, Optional


class SlidingWindowRateLimiter:
    """Thread-safe sliding window rate limiter."""

    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window_seconds = float(window_seconds)
        self._requests: Dict[str, List[float]] = {}
        self._lock = threading.Lock()

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        now = time.time() if timestamp is None else float(timestamp)
        with self._lock:
            if self.max_requests <= 0:
                return False, float('inf')

            timestamps = self._requests.setdefault(key, [])
            cutoff = now - self.window_seconds

            # Remove timestamps outside the sliding window
            idx = bisect.bisect_right(timestamps, cutoff)
            if idx > 0:
                del timestamps[:idx]

            if len(timestamps) < self.max_requests:
                if not timestamps or now >= timestamps[-1]:
                    timestamps.append(now)
                else:
                    bisect.insort(timestamps, now)
                return True, 0.0
            else:
                req_idx = len(timestamps) - self.max_requests
                oldest = timestamps[req_idx]
                retry_after = (oldest + self.window_seconds) - now
                return False, max(0.0, float(retry_after))

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        now = time.time() if timestamp is None else float(timestamp)
        with self._lock:
            if self.max_requests <= 0:
                return 0

            if key not in self._requests:
                return max(0, self.max_requests)

            timestamps = self._requests[key]
            cutoff = now - self.window_seconds

            idx = bisect.bisect_right(timestamps, cutoff)
            if idx > 0:
                del timestamps[:idx]

            if not timestamps:
                del self._requests[key]
                return max(0, self.max_requests)

            remaining = self.max_requests - len(timestamps)
            return max(0, remaining)
