import asyncio
import inspect
from typing import Optional


class AsyncWorkerPool:
    """An asynchronous worker pool using standard asyncio with priority queue support."""

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        self.concurrency = concurrency
        self.max_queue_size = max_queue_size
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: list[asyncio.Task] = []
        self._counter: int = 0
        self._is_started: bool = False
        self._is_shutting_down: bool = False
        self._is_shutdown: bool = False
        self._shutdown_event: asyncio.Event = asyncio.Event()

    async def start(self) -> None:
        """Spawns worker tasks."""
        if self._is_shutting_down or self._is_shutdown:
            raise RuntimeError("Pool is shutting down")
        if self._is_started:
            return
        self._is_started = True
        loop = asyncio.get_running_loop()
        for _ in range(self.concurrency):
            worker = loop.create_task(self._worker_loop())
            self._workers.append(worker)

    async def submit(self, coro_func, *args, priority: int = 0, **kwargs) -> asyncio.Future:
        """Enqueues a coroutine function coro_func(*args, **kwargs) to be executed by pool workers.

        Higher priority integers execute before lower priority integers.
        """
        if self._is_shutting_down or self._is_shutdown:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        fut = loop.create_future()
        self._counter += 1
        # Store negative priority because PriorityQueue pops smallest value first (min-heap)
        item = (-priority, self._counter, coro_func, args, kwargs, fut)

        await self._queue.put(item)

        if self._is_shutting_down or self._is_shutdown:
            if not fut.done():
                fut.cancel()
            raise RuntimeError("Pool is shutting down")

        return fut

    async def _worker_loop(self) -> None:
        loop = asyncio.get_running_loop()
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            _, _, coro_func, args, kwargs, fut = item
            try:
                if fut.done():
                    continue

                res = coro_func(*args, **kwargs)
                if inspect.isawaitable(res):
                    task = loop.create_task(res)

                    def _on_fut_done(f: asyncio.Future) -> None:
                        if f.cancelled() and not task.done():
                            task.cancel()

                    fut.add_done_callback(_on_fut_done)

                    try:
                        val = await task
                        if not fut.done():
                            fut.set_result(val)
                    except asyncio.CancelledError:
                        if not fut.done():
                            fut.cancel()
                        if asyncio.current_task().cancelled():
                            raise
                    except Exception as exc:
                        if not fut.done():
                            fut.set_exception(exc)
                else:
                    if not fut.done():
                        fut.set_result(res)
            except asyncio.CancelledError:
                if not fut.done():
                    fut.cancel()
                raise
            except Exception as exc:
                if not fut.done():
                    fut.set_exception(exc)
            finally:
                self._queue.task_done()

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        """Shuts down the worker pool.

        If drain=True, waits for enqueued tasks to finish before stopping workers.
        If drain=False, cancels queued and executing tasks immediately.
        Respects optional timeout seconds.
        """
        if self._is_shutdown:
            return
        if self._is_shutting_down:
            if timeout is not None:
                await asyncio.wait_for(self._shutdown_event.wait(), timeout=timeout)
            else:
                await self._shutdown_event.wait()
            return

        self._is_shutting_down = True

        try:
            if timeout is not None:
                await asyncio.wait_for(self._do_shutdown(drain), timeout=timeout)
            else:
                await self._do_shutdown(drain)
        except (asyncio.TimeoutError, TimeoutError):
            await self._do_shutdown(drain=False)
            raise asyncio.TimeoutError("Shutdown timed out")
        finally:
            self._is_shutdown = True
            self._shutdown_event.set()

    async def _do_shutdown(self, drain: bool) -> None:
        if drain:
            await self._queue.join()
            for worker in self._workers:
                if not worker.done():
                    worker.cancel()
            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)
        else:
            self._clear_queue()

            for worker in self._workers:
                if not worker.done():
                    worker.cancel()
            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)

            self._clear_queue()

    def _clear_queue(self) -> None:
        while True:
            try:
                item = self._queue.get_nowait()
            except asyncio.QueueEmpty:
                break
            _, _, _, _, _, fut = item
            if not fut.done():
                fut.cancel()
            self._queue.task_done()
