class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        self.node_ids: list[str] = list(node_ids)
        self.N: int = len(self.node_ids)
        self.quorum_threshold: int = self.N // 2 + 1

        all_nodes = set(self.node_ids)
        self.active_partitions: dict[str, set[str]] = {
            n: set(all_nodes) for n in self.node_ids
        }
        self.node_data: dict[str, dict[str, tuple[any, int]]] = {
            n: {} for n in self.node_ids
        }
        self.clock: int = 0

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        set_a = set(group_a) & set(self.node_ids)
        set_b = set(group_b) & set(self.node_ids)
        for n in self.node_ids:
            if n in set_a:
                self.active_partitions[n] = set_a
            elif n in set_b:
                self.active_partitions[n] = set_b
            else:
                self.active_partitions[n] = {n}

    def heal_partition(self) -> None:
        all_nodes = set(self.node_ids)
        for n in self.node_ids:
            self.active_partitions[n] = set(all_nodes)

        latest_state: dict[str, tuple[any, int]] = {}
        for node in self.node_ids:
            for key, (val, ver) in self.node_data[node].items():
                if key not in latest_state or ver > latest_state[key][1]:
                    latest_state[key] = (val, ver)

        for node in self.node_ids:
            self.node_data[node] = dict(latest_state)

    def propose_write(self, from_node: str, key: str, value: any) -> bool:
        if from_node not in self.node_ids:
            return False

        partition_nodes = self.active_partitions.get(from_node, set())
        if len(partition_nodes) >= self.quorum_threshold:
            self.clock += 1
            for node in partition_nodes:
                if node in self.node_data:
                    self.node_data[node][key] = (value, self.clock)
            return True
        return False

    def read_value(self, from_node: str, key: str) -> any:
        if from_node not in self.node_data:
            return None
        if key in self.node_data[from_node]:
            return self.node_data[from_node][key][0]
        return None
