import threading


class ResilientConnectionPool:

  def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
    self.max_connections = max_connections
    self.ping_timeout = ping_timeout
    self._lock = threading.Lock()
    self._next_id = 1
    self._pool = []
    self._in_use = []

    for _ in range(max_connections):
      self._pool.append({"id": self._next_id, "alive": True})
      self._next_id += 1

  def acquire(self) -> dict:
    with self._lock:
      if not self._pool:
        raise RuntimeError("Pool exhausted")
      conn = self._pool.pop(0)
      if not conn.get("alive", False):
        conn = {"id": self._next_id, "alive": True}
        self._next_id += 1
      self._in_use.append(conn)
      return conn

  def release(self, conn: dict) -> None:
    with self._lock:
      if not isinstance(conn, dict):
        return
      self._in_use = [c for c in self._in_use if c is not conn]
      if not any(c is conn for c in self._pool):
        self._pool.append(conn)

  def health_check_and_heal(self) -> int:
    with self._lock:
      healed_count = 0
      for i in range(len(self._pool)):
        conn = self._pool[i]
        if not conn.get("alive", False):
          self._pool[i] = {"id": self._next_id, "alive": True}
          self._next_id += 1
          healed_count += 1
      return healed_count

  def close_all(self) -> None:
    with self._lock:
      for conn in self._pool:
        conn["alive"] = False
      for conn in self._in_use:
        conn["alive"] = False
      self._pool.clear()
      self._in_use.clear()
