import ast
import re


def prune_dead_code_and_imports(source_code: str) -> str:
    """Refactors Python source code by removing unused imports and dead top-level private functions.

    - Unused imports (including composite from-imports) are removed or rewritten.
    - Top-level private functions (names starting with '_') are removed if unreferenced.
    - Public functions, class definitions, global assignments, and module docstrings are preserved.
    - The returned code is syntactically valid and compiles cleanly.
    """
    tree = ast.parse(source_code)

    def get_referenced_names(node: ast.AST) -> set[str]:
        names = set()
        for child in ast.walk(node):
            # Collect variable, function, and module names in Load context
            if isinstance(child, ast.Name) and isinstance(child.ctx, ast.Load):
                names.add(child.id)
            # Collect global and nonlocal symbol declarations
            elif isinstance(child, (ast.Global, ast.Nonlocal)):
                names.update(child.names)
            # Collect string identifiers in __all__ exports
            elif isinstance(child, (ast.Assign, ast.AugAssign)):
                targets = child.targets if isinstance(child, ast.Assign) else [child.target]
                for target in targets:
                    if isinstance(target, ast.Name) and target.id == '__all__':
                        for sub in ast.walk(child.value):
                            if isinstance(sub, ast.Constant) and isinstance(sub.value, str):
                                names.add(sub.value)

            # Handle string type annotations if present
            if hasattr(child, 'annotation') and child.annotation is not None:
                if isinstance(child.annotation, ast.Constant) and isinstance(child.annotation.value, str):
                    for match in re.findall(r'\b[A-Za-z_][A-Za-z0-9_]*\b', child.annotation.value):
                        names.add(match)
            if hasattr(child, 'returns') and child.returns is not None:
                if isinstance(child.returns, ast.Constant) and isinstance(child.returns.value, str):
                    for match in re.findall(r'\b[A-Za-z_][A-Za-z0-9_]*\b', child.returns.value):
                        names.add(match)
        return names

    private_func_map: dict[str, list[ast.FunctionDef | ast.AsyncFunctionDef]] = {}
    roots: list[ast.AST] = []

    # Separate top-level statements into Roots and private function candidates
    for stmt in tree.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
            # Check if top-level function is private (starts with '_') and not a dunder hook like '__getattr__'
            if stmt.name.startswith('_') and not (stmt.name.startswith('__') and stmt.name.endswith('__')):
                if stmt.name not in private_func_map:
                    private_func_map[stmt.name] = []
                private_func_map[stmt.name].append(stmt)
            else:
                roots.append(stmt)
        elif isinstance(stmt, (ast.Import, ast.ImportFrom)):
            if isinstance(stmt, ast.ImportFrom):
                # Always preserve __future__ imports and star imports
                if stmt.module == '__future__' or any(alias_node.name == '*' for alias_node in stmt.names):
                    roots.append(stmt)
        else:
            # Preserved roots: ClassDef, Assign, AnnAssign, AugAssign, Expr (docstrings), etc.
            roots.append(stmt)

    # Perform graph reachability / mark phase to find all live symbols
    live_symbols: set[str] = set()
    worklist: list[ast.AST] = list(roots)
    visited_node_ids: set[int] = set()

    while worklist:
        curr = worklist.pop()
        curr_id = id(curr)
        if curr_id in visited_node_ids:
            continue
        visited_node_ids.add(curr_id)

        ref_names = get_referenced_names(curr)
        for name in ref_names:
            if name not in live_symbols:
                live_symbols.add(name)
                if name in private_func_map:
                    for func_node in private_func_map[name]:
                        worklist.append(func_node)

    # AST Transformer for the sweep phase
    class Pruner(ast.NodeTransformer):
        def visit_Module(self, node: ast.Module) -> ast.Module:
            new_body = []
            for stmt in node.body:
                if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    if stmt.name.startswith('_') and not (stmt.name.startswith('__') and stmt.name.endswith('__')):
                        if stmt.name not in live_symbols:
                            # Prune dead private top-level function
                            continue
                transformed = self.visit(stmt)
                if transformed is not None:
                    if isinstance(transformed, list):
                        new_body.extend(transformed)
                    else:
                        new_body.append(transformed)
            node.body = new_body
            return node

        def visit_Import(self, node: ast.Import) -> ast.Import | None:
            new_names = []
            for alias_node in node.names:
                bound = alias_node.asname if alias_node.asname else alias_node.name.split('.')[0]
                if bound in live_symbols:
                    new_names.append(alias_node)
            if not new_names:
                return None
            node.names = new_names
            return node

        def visit_ImportFrom(self, node: ast.ImportFrom) -> ast.ImportFrom | None:
            if node.module == '__future__':
                return node
            new_names = []
            for alias_node in node.names:
                if alias_node.name == '*':
                    new_names.append(alias_node)
                else:
                    bound = alias_node.asname if alias_node.asname else alias_node.name
                    if bound in live_symbols:
                        new_names.append(alias_node)
            if not new_names:
                return None
            node.names = new_names
            return node

    new_tree = Pruner().visit(tree)
    ast.fix_missing_locations(new_tree)
    res = ast.unparse(new_tree)
    compile(res, '<string>', 'exec')
    return res
