import os
import posixpath
import stat
import unicodedata
import zipfile
from pathlib import PurePosixPath, PureWindowsPath


def safe_extract_zip(
    archive_path: str,
    destination: str,
    max_files: int = 1000,
    max_uncompressed_bytes: int = 10000000,
    max_compression_ratio: float = 100.0,
) -> list[str]:
    try:
        archive = zipfile.ZipFile(archive_path, "r")
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid ZIP archive: {e}") from e

    with archive:
        infolist = archive.infolist()

        seen_entry_paths = set()
        seen_files = set()
        seen_parent_dirs = set()

        file_count = 0
        total_uncompressed_bytes = 0

        file_entries_to_extract = []
        dir_entries_to_extract = []

        dest_abs = os.path.abspath(destination)

        # Validation phase: validate entire archive before writing anything
        for info in infolist:
            raw_name = info.filename

            # Check for NUL byte
            if "\x00" in raw_name:
                raise ValueError(
                    f"Archive entry contains a NUL byte: {raw_name!r}"
                )

            # Check for absolute path
            if (
                raw_name.startswith("/")
                or raw_name.startswith("\\")
                or bool(PureWindowsPath(raw_name).drive)
                or PurePosixPath(raw_name).is_absolute()
                or PureWindowsPath(raw_name).is_absolute()
            ):
                raise ValueError(
                    f"Archive entry is an absolute path: {raw_name!r}"
                )

            # Unicode NFC normalization
            nfc_name = unicodedata.normalize("NFC", raw_name)

            # Convert backslashes to forward slashes for POSIX relative path calculation
            posix_name = nfc_name.replace("\\", "/")

            # Check for '..' escape using either slash style
            parts = posix_name.split("/")
            depth = 0
            for part in parts:
                if part == "" or part == ".":
                    continue
                elif part == "..":
                    depth -= 1
                    if depth < 0:
                        raise ValueError(
                            f"Archive entry escapes destination directory via '..': {raw_name!r}"
                        )
                else:
                    depth += 1

            rel_path = posixpath.normpath(posix_name)
            if rel_path in (".", "..") or rel_path.startswith("../"):
                raise ValueError(
                    f"Archive entry resolves outside destination: {raw_name!r}"
                )

            target_abs = os.path.abspath(
                os.path.join(dest_abs, *rel_path.split("/"))
            )
            try:
                common = os.path.commonpath([dest_abs, target_abs])
            except ValueError:
                raise ValueError(
                    f"Archive entry target is invalid or on a different drive: {raw_name!r}"
                )
            if common != dest_abs:
                raise ValueError(
                    f"Archive entry escapes destination directory: {raw_name!r}"
                )

            # Check for Unix symlink
            mode = info.external_attr >> 16
            if mode and stat.S_ISLNK(mode):
                raise ValueError(
                    f"Archive entry is a Unix symlink: {raw_name!r}"
                )

            # Determine if entry is a directory
            is_dir = (
                info.is_dir()
                or raw_name.endswith("/")
                or raw_name.endswith("\\")
                or bool(mode and stat.S_ISDIR(mode))
            )

            # Collision check after Unicode NFC normalization
            if rel_path in seen_entry_paths:
                raise ValueError(
                    f"Archive entry collides with another entry after NFC normalization: {rel_path!r}"
                )
            seen_entry_paths.add(rel_path)

            if is_dir:
                dir_entries_to_extract.append((info, rel_path))
            else:
                if rel_path in seen_parent_dirs:
                    raise ValueError(
                        f"File entry collides with a parent directory of another file: {rel_path!r}"
                    )

                path_parts = rel_path.split("/")
                for i in range(1, len(path_parts)):
                    parent = "/".join(path_parts[:i])
                    if parent in seen_files:
                        raise ValueError(
                            f"Parent directory of file collides with an existing file entry: {parent!r}"
                        )
                    seen_parent_dirs.add(parent)

                seen_files.add(rel_path)

                # Check file count limit (directory entries do not count as files)
                file_count += 1
                if file_count > max_files:
                    raise ValueError(
                        f"File count ({file_count}) exceeds limit of {max_files}"
                    )

                # Check cumulative uncompressed size limit
                total_uncompressed_bytes += info.file_size
                if total_uncompressed_bytes > max_uncompressed_bytes:
                    raise ValueError(
                        f"Cumulative uncompressed bytes ({total_uncompressed_bytes}) exceeds limit of {max_uncompressed_bytes}"
                    )

                # Check per-file compression ratio limit
                if info.compress_size == 0:
                    if info.file_size > 0:
                        raise ValueError(
                            f"Per-file compression ratio for {rel_path!r} exceeds limit of {max_compression_ratio}"
                        )
                    ratio = 0.0
                else:
                    ratio = info.file_size / info.compress_size

                if ratio > max_compression_ratio:
                    raise ValueError(
                        f"Per-file compression ratio ({ratio}) for {rel_path!r} exceeds limit of {max_compression_ratio}"
                    )

                file_entries_to_extract.append((info, rel_path))

        # Extraction phase: executed only if all entries are valid
        os.makedirs(dest_abs, exist_ok=True)

        for info, rel_path in dir_entries_to_extract:
            dir_target = os.path.join(dest_abs, *rel_path.split("/"))
            os.makedirs(dir_target, exist_ok=True)

        extracted_files = []
        for info, rel_path in file_entries_to_extract:
            file_target = os.path.join(dest_abs, *rel_path.split("/"))
            os.makedirs(os.path.dirname(file_target), exist_ok=True)
            with archive.open(info, "r") as src, open(file_target, "wb") as dst:
                while chunk := src.read(65536):
                    dst.write(chunk)
            extracted_files.append(rel_path)

        return sorted(extracted_files)
