import fnmatch


def authorize(request: dict, policies: list[dict]) -> bool:
    """
    Evaluates an authorization request against a set of access control policies.

    :param request: Dictionary representing the authorization request.
    :param policies: List of policy dictionaries defining access controls.
    :return: True if authorized (at least one allow matches and no deny matches), else False.
    """
    # 1. Validate request structure and non-empty fields
    if not isinstance(request, dict):
        return False

    required_request_keys = {
        'subject_id', 'tenant_id', 'resource_tenant_id',
        'roles', 'action', 'resource', 'context'
    }
    if not required_request_keys.issubset(request.keys()):
        return False

    sub_id = request['subject_id']
    t_id = request['tenant_id']
    res_t_id = request['resource_tenant_id']
    roles = request['roles']
    action = request['action']
    resource = request['resource']
    context = request['context']

    if not (isinstance(sub_id, str) and len(sub_id) > 0):
        return False
    if not (isinstance(t_id, str) and len(t_id) > 0):
        return False
    if not (isinstance(res_t_id, str) and len(res_t_id) > 0):
        return False
    if not (isinstance(action, str) and len(action) > 0):
        return False
    if not (isinstance(resource, str) and len(resource) > 0):
        return False
    if not isinstance(context, dict):
        return False
    if not (isinstance(roles, list) and len(roles) > 0 and all(isinstance(r, str) and len(r) > 0 for r in roles)):
        return False

    # Check tenant isolation rule
    if t_id != res_t_id:
        return False

    # 2. Validate policies structure (fail closed if any policy is malformed)
    if not isinstance(policies, list):
        return False

    required_policy_keys = {'effect', 'tenant', 'roles', 'actions', 'resources'}
    for p in policies:
        if not isinstance(p, dict):
            return False
        if not required_policy_keys.issubset(p.keys()):
            return False
        if not (isinstance(p['effect'], str) and p['effect'] in ('allow', 'deny')):
            return False
        if not (isinstance(p['tenant'], str) and len(p['tenant']) > 0):
            return False
        if not (isinstance(p['roles'], list) and len(p['roles']) > 0 and all(isinstance(r, str) and len(r) > 0 for r in p['roles'])):
            return False
        if not (isinstance(p['actions'], list) and len(p['actions']) > 0 and all(isinstance(a, str) and len(a) > 0 for a in p['actions'])):
            return False
        if not (isinstance(p['resources'], list) and len(p['resources']) > 0 and all(isinstance(res, str) and len(res) > 0 for res in p['resources'])):
            return False
        if 'conditions' in p and not isinstance(p['conditions'], dict):
            return False

    # 3. Evaluate matching policies
    allow_matched = False

    for p in policies:
        # Tenant match
        p_tenant = p['tenant']
        if not (p_tenant == '*' or p_tenant == t_id):
            continue

        # Role match
        p_roles = p['roles']
        role_matched = False
        for pr in p_roles:
            for rr in roles:
                if pr == '*' or rr == '*' or pr == rr or fnmatch.fnmatchcase(rr, pr):
                    role_matched = True
                    break
            if role_matched:
                break
        if not role_matched:
            continue

        # Action match using case-sensitive shell pattern
        p_actions = p['actions']
        if not any(fnmatch.fnmatchcase(action, act_pat) for act_pat in p_actions):
            continue

        # Resource match using case-sensitive shell pattern
        p_resources = p['resources']
        if not any(fnmatch.fnmatchcase(resource, res_pat) for res_pat in p_resources):
            continue

        # Conditions match
        p_conditions = p.get('conditions')
        if p_conditions:
            cond_matched = True
            for c_key, c_val in p_conditions.items():
                if c_key not in context:
                    cond_matched = False
                    break
                ctx_val = context[c_key]
                if isinstance(c_val, (list, tuple)):
                    if isinstance(ctx_val, (list, tuple, set)):
                        if not (ctx_val in c_val or any(item in c_val for item in ctx_val)):
                            cond_matched = False
                            break
                    else:
                        if ctx_val not in c_val:
                            cond_matched = False
                            break
                else:
                    if ctx_val != c_val:
                        cond_matched = False
                        break
            if not cond_matched:
                continue

        # Handle policy match effect
        if p['effect'] == 'deny':
            return False
        elif p['effect'] == 'allow':
            allow_matched = True

    return allow_matched
