import re
from decimal import Decimal

class PaymentLedger:
    def __init__(self):
        self._seen_events = {}
        self._payment_applied_seqs = {}
        self._payment_buffered_events = {}
        self._payment_states = {}

    def _validate_event(self, event: dict) -> None:
        if not isinstance(event, dict):
            raise ValueError("Event must be a dictionary")

        required_keys = {'event_id', 'payment_id', 'sequence', 'type', 'amount'}
        if set(event.keys()) != required_keys:
            raise ValueError(f"Event must contain exactly required keys: {required_keys}")

        event_id = event['event_id']
        if not isinstance(event_id, str) or not event_id:
            raise ValueError("event_id must be a non-empty string")

        payment_id = event['payment_id']
        if not isinstance(payment_id, str) or not payment_id:
            raise ValueError("payment_id must be a non-empty string")

        seq = event['sequence']
        if type(seq) is not int or seq <= 0:
            raise ValueError("sequence must be a positive integer")

        event_type = event['type']
        if event_type not in ('authorized', 'captured', 'refunded', 'reversed'):
            raise ValueError(f"Invalid event type: {event_type}")

        amount_str = event['amount']
        if not isinstance(amount_str, str) or not re.match(r'^\d+(\.\d{1,2})?$', amount_str):
            raise ValueError("amount must be a positive decimal string with at most two fractional digits")

        try:
            amount_dec = Decimal(amount_str)
        except Exception:
            raise ValueError("amount is not a valid Decimal")

        if amount_dec <= Decimal('0'):
            raise ValueError("amount must be positive")

    def apply(self, event: dict) -> str:
        self._validate_event(event)

        event_id = event['event_id']
        payment_id = event['payment_id']
        seq = event['sequence']

        # Global event_id check
        if event_id in self._seen_events:
            existing = self._seen_events[event_id]
            if existing == event:
                return "duplicate"
            else:
                raise ValueError(f"Event ID {event_id} reused with different content")

        # Sequence check for payment_id
        if payment_id in self._payment_applied_seqs and seq in self._payment_applied_seqs[payment_id]:
            raise ValueError(f"Sequence {seq} already applied for payment {payment_id}")

        if payment_id in self._payment_buffered_events and seq in self._payment_buffered_events[payment_id]:
            raise ValueError(f"Sequence {seq} already buffered for payment {payment_id}")

        # Expected next sequence
        if payment_id in self._payment_states:
            next_seq = self._payment_states[payment_id]['next_sequence']
        else:
            next_seq = 1

        if seq > next_seq:
            if payment_id not in self._payment_buffered_events:
                self._payment_buffered_events[payment_id] = {}
            self._payment_buffered_events[payment_id][seq] = dict(event)
            self._seen_events[event_id] = dict(event)
            return "buffered"

        if seq < next_seq:
            raise ValueError(f"Sequence {seq} is less than next expected sequence {next_seq}")

        # seq == next_seq: form consecutive chain of events starting from seq
        chain = [dict(event)]
        curr_s = seq + 1
        buffered = self._payment_buffered_events.get(payment_id, {})
        while curr_s in buffered:
            chain.append(buffered[curr_s])
            curr_s += 1

        # Speculatively apply the sequence chain
        if payment_id in self._payment_states:
            st = self._payment_states[payment_id]
            auth = st['authorized']
            cap = st['captured']
            ref = st['refunded']
            rev = st['reversed']
        else:
            auth = Decimal('0')
            cap = Decimal('0')
            ref = Decimal('0')
            rev = Decimal('0')

        for item in chain:
            item_seq = item['sequence']
            item_type = item['type']
            item_amt = Decimal(item['amount'])

            if item_seq == 1 and item_type != 'authorized':
                raise ValueError("Sequence 1 must be authorized")

            if item_type == 'authorized':
                auth += item_amt
            elif item_type == 'captured':
                avail = auth - cap
                if item_amt > avail:
                    raise ValueError("Captures cannot exceed authorization")
                cap += item_amt
            elif item_type == 'refunded':
                settled_remaining = cap - ref - rev
                if item_amt > settled_remaining:
                    raise ValueError("Refunds cannot exceed remaining settled amount")
                ref += item_amt
            elif item_type == 'reversed':
                settled_remaining = cap - ref - rev
                if item_amt > settled_remaining:
                    raise ValueError("Reversals cannot exceed remaining settled amount")
                rev += item_amt

        # Commit state updates after successful validation
        if payment_id not in self._payment_applied_seqs:
            self._payment_applied_seqs[payment_id] = set()

        for item in chain:
            item_id = item['event_id']
            item_s = item['sequence']
            self._seen_events[item_id] = item
            self._payment_applied_seqs[payment_id].add(item_s)
            if payment_id in self._payment_buffered_events:
                self._payment_buffered_events[payment_id].pop(item_s, None)

        self._payment_states[payment_id] = {
            'authorized': auth,
            'captured': cap,
            'refunded': ref,
            'reversed': rev,
            'next_sequence': curr_s
        }

        return "applied"

    def state(self, payment_id: str) -> dict | None:
        if payment_id not in self._payment_states:
            return None

        st = self._payment_states[payment_id]
        auth = st['authorized']
        cap = st['captured']
        ref = st['refunded']
        rev = st['reversed']

        avail = auth - cap
        merch = cap - ref - rev

        return {
            "authorized": f"{auth:.2f}",
            "captured": f"{cap:.2f}",
            "refunded": f"{ref:.2f}",
            "reversed": f"{rev:.2f}",
            "available_to_capture": f"{avail:.2f}",
            "merchant_balance": f"{merch:.2f}",
            "next_sequence": st['next_sequence']
        }

    def snapshot(self) -> dict:
        result = {}
        for pid in sorted(self._payment_states.keys()):
            st_dict = self.state(pid)
            if st_dict is not None:
                result[pid] = st_dict
        return result
