class RetryableError(Exception):
    pass


class FatalError(Exception):
    pass


class CrashError(Exception):
    pass


class SagaOrchestrator:
    def __init__(
        self,
        executor,
        compensator,
        max_retries: int = 2,
        journal: dict | None = None,
    ):
        if not isinstance(max_retries, int) or max_retries < 0:
            raise ValueError("max_retries must be a non-negative integer")
        self.executor = executor
        self.compensator = compensator
        self.max_retries = max_retries
        if journal is None:
            self.journal = {}
        else:
            self.journal = journal

    def _validate(self, saga_id: str, steps: list[str]):
        if not isinstance(saga_id, str) or not saga_id:
            raise ValueError("saga_id must be a non-empty string")
        if not isinstance(steps, list) or not steps:
            raise ValueError("steps must be a non-empty list of strings")
        for step in steps:
            if not isinstance(step, str) or not step:
                raise ValueError("each step must be a non-empty string")
        if len(set(steps)) != len(steps):
            raise ValueError("steps must be unique non-empty strings")
        if saga_id in self.journal:
            existing_steps = self.journal[saga_id].get("steps")
            if existing_steps != steps:
                raise ValueError("Step plan does not match existing saga plan")

    def run(self, saga_id: str, steps: list[str]) -> str:
        return self._orchestrate(saga_id, steps)

    def recover(self, saga_id: str, steps: list[str]) -> str:
        return self._orchestrate(saga_id, steps)

    def _orchestrate(self, saga_id: str, steps: list[str]) -> str:
        self._validate(saga_id, steps)

        if saga_id not in self.journal:
            self.journal[saga_id] = {
                "steps": list(steps),
                "completed": [],
                "compensated": [],
                "status": "executing",
            }

        saga = self.journal[saga_id]
        status = saga.get("status", "executing")

        if status == "completed":
            return "completed"
        if status == "compensated":
            return "compensated"

        if status == "compensating":
            return self._compensate(saga_id)

        completed = saga["completed"]
        for step in steps:
            if step in completed:
                continue

            attempts = 0
            step_failed = False
            while True:
                try:
                    self.executor(step)
                    completed.append(step)
                    break
                except CrashError:
                    raise
                except RetryableError:
                    if attempts < self.max_retries:
                        attempts += 1
                        continue
                    else:
                        step_failed = True
                        break
                except Exception:
                    step_failed = True
                    break

            if step_failed:
                return self._compensate(saga_id)

        saga["status"] = "completed"
        return "completed"

    def _compensate(self, saga_id: str) -> str:
        saga = self.journal[saga_id]
        saga["status"] = "compensating"

        completed = saga["completed"]
        compensated = saga["compensated"]

        for step in reversed(completed):
            if step in compensated:
                continue

            attempts = 0
            while True:
                try:
                    self.compensator(step)
                    compensated.append(step)
                    break
                except CrashError:
                    raise
                except RetryableError:
                    if attempts < self.max_retries:
                        attempts += 1
                        continue
                    else:
                        raise
                except Exception:
                    raise

        saga["status"] = "compensated"
        return "compensated"
