import time
import threading
from collections import OrderedDict
from typing import Optional, Any

class TimeBoundedLRUCache:
    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        if capacity <= 0:
            raise ValueError("Capacity must be greater than 0")
        self.capacity = capacity
        self.default_ttl = default_ttl_seconds
        # OrderedDict maintains insertion/access order.
        # Store as: {key: (value, expiration_time)}
        self.cache: OrderedDict[str, tuple[Any, float]] = OrderedDict()
        self.lock = threading.RLock()

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        with self.lock:
            if ttl is None:
                ttl = self.default_ttl

            expiry_time = time.time() + ttl

            if key in self.cache:
                # If key already exists, remove it first to update its position 
                # (recency) when we insert it again
                self.cache.pop(key)
            else:
                if len(self.cache) >= self.capacity:
                    self._evict(time.time())

            self.cache[key] = (value, expiry_time)

    def _evict(self, now: float) -> None:
        # Must be called with lock held
        oldest_exp_key = None
        oldest_exp_time = float('inf')

        # Scan for the oldest expired item
        for k, (v, exp) in self.cache.items():
            if exp <= now:
                if exp < oldest_exp_time:
                    oldest_exp_time = exp
                    oldest_exp_key = k

        if oldest_exp_key is not None:
            # Evict the oldest expired item
            self.cache.pop(oldest_exp_key)
        else:
            # No expired items found, evict the least recently used item (first item)
            self.cache.popitem(last=False)

    def get(self, key: str) -> Optional[Any]:
        with self.lock:
            if key in self.cache:
                value, expiry_time = self.cache[key]
                if expiry_time > time.time():
                    # Valid item found, move to end to mark it as most recently used
                    self.cache.move_to_end(key)
                    return value
                else:
                    # Item has expired, remove it proactively
                    self.cache.pop(key)
                    return None
            return None

    def delete(self, key: str) -> bool:
        with self.lock:
            if key in self.cache:
                self.cache.pop(key)
                return True
            return False

    def cleanup_expired(self) -> int:
        count = 0
        now = time.time()
        with self.lock:
            # Identify all expired keys
            keys_to_delete = [k for k, (v, exp) in self.cache.items() if exp <= now]

            # Remove them
            for k in keys_to_delete:
                self.cache.pop(k, None)
                count += 1

            return count

    def size(self) -> int:
        now = time.time()
        with self.lock:
            return sum(1 for v, exp in self.cache.values() if exp > now)

