import time
import threading
from collections import defaultdict, deque
from typing import Optional

class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        if max_requests <= 0:
            raise ValueError("max_requests must be greater than 0")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be greater than 0")

        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self.requests = defaultdict(deque)
        self.lock = threading.Lock()

    def _cleanup(self, key: str, current_time: float) -> None:
        # Assumes lock is already acquired by the calling method
        window_start = current_time - self.window_seconds
        q = self.requests[key]
        while q and q[0] <= window_start:
            q.popleft()

        # Optional: clean up empty deques to prevent memory leaks for unused keys
        if not q and key in self.requests:
            del self.requests[key]

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            self._cleanup(key, timestamp)

            # Since _cleanup might have deleted the key, we re-access it which creates a new deque if needed
            q = self.requests[key]

            if len(q) < self.max_requests:
                q.append(timestamp)
                return True, 0.0
            else:
                # The oldest request in the window is at q[0]
                retry_after = (q[0] + self.window_seconds) - timestamp
                return False, max(0.0, retry_after)

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            self._cleanup(key, timestamp)
            # Use get to avoid recreating the deque if it was cleaned up
            q_len = len(self.requests.get(key, []))
            return max(0, self.max_requests - q_len)
