class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        self.node_ids = node_ids
        self.quorum = len(node_ids) // 2 + 1
        # By default, all nodes can communicate with each other
        self.partitions = {node: set(node_ids) for node in node_ids}

        # State and version tracking per node to handle synchronization
        self.store = {node: {} for node in node_ids}
        self.versions = {node: {} for node in node_ids}
        self.global_version = 0

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """Divides cluster into two isolated network partitions."""
        set_a = set(group_a)
        set_b = set(group_b)
        for node in group_a:
            self.partitions[node] = set_a
        for node in group_b:
            self.partitions[node] = set_b

    def heal_partition(self) -> None:
        """Restores full connectivity and synchronizes committed state."""
        # Restore full connectivity
        for node in self.node_ids:
            self.partitions[node] = set(self.node_ids)

        # Synchronize committed state across all nodes by finding the latest version
        # for each key across the entire cluster.
        latest_versions = {}
        latest_values = {}

        for node in self.node_ids:
            for key, version in self.versions[node].items():
                if key not in latest_versions or version > latest_versions[key]:
                    latest_versions[key] = version
                    latest_values[key] = self.store[node][key]

        # Apply the latest states to all nodes
        for node in self.node_ids:
            for key in latest_values:
                self.store[node][key] = latest_values[key]
                self.versions[node][key] = latest_versions[key]

    def propose_write(self, from_node: str, key: str, value: any) -> bool:
        """Proposes a write, committing it only if the partition has a strict majority."""
        reachable_nodes = self.partitions.get(from_node, set())

        # Check if the node's partition meets the quorum threshold
        if len(reachable_nodes) >= self.quorum:
            self.global_version += 1
            current_version = self.global_version

            # Commit the write and update state in all reachable nodes
            for node in reachable_nodes:
                self.store[node][key] = value
                self.versions[node][key] = current_version
            return True

        # Rejected due to minority partition (split-brain prevention)
        return False

    def read_value(self, from_node: str, key: str) -> any:
        """Returns the committed value for the key on the given node."""
        return self.store.get(from_node, {}).get(key, None)
