import ast

def prune_dead_code_and_imports(source_code: str) -> str:
    tree = ast.parse(source_code)

    class UsageVisitor(ast.NodeVisitor):
        def __init__(self):
            self.used_names = set()

        def visit_Name(self, node):
            if isinstance(node.ctx, ast.Load):
                self.used_names.add(node.id)
            self.generic_visit(node)

        def visit_Global(self, node):
            self.used_names.update(node.names)
            self.generic_visit(node)

        def visit_Nonlocal(self, node):
            self.used_names.update(node.names)
            self.generic_visit(node)

    def get_used_names(node):
        visitor = UsageVisitor()
        visitor.visit(node)
        return visitor.used_names

    alive_names = set()
    alive_stmts = set()
    dead_candidates = set()

    for stmt in tree.body:
        is_private_func = isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith('_')
        is_import = isinstance(stmt, (ast.Import, ast.ImportFrom))

        if is_private_func or is_import:
            dead_candidates.add(stmt)
        else:
            alive_stmts.add(stmt)
            alive_names.update(get_used_names(stmt))

    # Fixed-point iteration to handle transitive dependencies
    while True:
        added_new = False
        for stmt in dead_candidates:
            if stmt in alive_stmts:
                continue

            if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)):
                if stmt.name in alive_names:
                    alive_stmts.add(stmt)
                    alive_names.update(get_used_names(stmt))
                    added_new = True
        if not added_new:
            break

    new_body = []
    for stmt in tree.body:
        if stmt in alive_stmts:
            new_body.append(stmt)
        elif isinstance(stmt, ast.Import):
            new_names = []
            for alias in stmt.names:
                bound_name = alias.asname if alias.asname else alias.name.split('.')[0]
                if bound_name in alive_names:
                    new_names.append(alias)
            if new_names:
                stmt.names = new_names
                new_body.append(stmt)
        elif isinstance(stmt, ast.ImportFrom):
            new_names = []
            for alias in stmt.names:
                if alias.name == '*':
                    new_names.append(alias)
                    continue
                bound_name = alias.asname if alias.asname else alias.name
                if bound_name in alive_names:
                    new_names.append(alias)
            if new_names:
                stmt.names = new_names
                new_body.append(stmt)

    tree.body = new_body
    return ast.unparse(tree)
