import os
import stat
import shutil
import zipfile
import unicodedata

def safe_extract_zip(archive_path: str, destination: str, max_files: int = 1000, 
                     max_uncompressed_bytes: int = 10000000, max_compression_ratio: float = 100.0) -> list[str]:
    def is_directory(entry: zipfile.ZipInfo) -> bool:
        if entry.is_dir():
            return True
        mode = entry.external_attr >> 16
        if mode != 0 and stat.S_ISDIR(mode):
            return True
        return False

    def resolve_path_and_check_escape(filename: str) -> str:
        if '\x00' in filename:
            raise ValueError("NUL byte in filename")
        if filename.startswith('/') or filename.startswith('\\'):
            raise ValueError("Absolute path")
        if len(filename) >= 2 and filename[1] == ':':
            raise ValueError("Absolute path with drive letter")

        parts = filename.replace('\\', '/').split('/')
        resolved = []
        depth = 0
        for part in parts:
            if part == '..':
                depth -= 1
                if depth < 0:
                    raise ValueError("Escapes through ..")
                if resolved:
                    resolved.pop()
            elif part not in ('', '.'):
                depth += 1
                resolved.append(part)
        return '/'.join(resolved)

    seen_names = set()
    file_count = 0
    total_size = 0
    norm_names = []

    with zipfile.ZipFile(archive_path, 'r') as zf:
        entries = zf.infolist()

        # Pass 1: Validate entire archive before extraction
        for entry in entries:
            # Check for Unix symlink
            mode = entry.external_attr >> 16
            if stat.S_ISLNK(mode):
                raise ValueError("Unix symlink detected")

            # Check path escaping and normalise
            resolved_posix = resolve_path_and_check_escape(entry.filename)
            norm_name = unicodedata.normalize('NFC', resolved_posix)

            if not norm_name and not is_directory(entry):
                raise ValueError("File resolves to root directory")

            # Check for NFC-normalized name collisions
            if norm_name:
                if norm_name in seen_names:
                    raise ValueError(f"Collision detected: {norm_name}")
                seen_names.add(norm_name)

            norm_names.append(norm_name)

            # Enforce limits (directories do not count as files)
            if not is_directory(entry):
                file_count += 1
                if file_count > max_files:
                    raise ValueError("Exceeds max files limit")

                total_size += entry.file_size
                if total_size > max_uncompressed_bytes:
                    raise ValueError("Exceeds cumulative uncompressed-size limit")

                if entry.compress_size == 0:
                    if entry.file_size > 0:
                        raise ValueError("Infinite compression ratio")
                else:
                    ratio = entry.file_size / entry.compress_size
                    if ratio > max_compression_ratio:
                        raise ValueError("Exceeds per-file compression-ratio limit")

        # Pass 2: Extract verified files safely
        extracted_files = []
        for entry, norm_name in zip(entries, norm_names):
            if is_directory(entry) or not norm_name:
                continue

            # Safely create target path beneath destination
            target_path = os.path.join(destination, os.path.normpath(norm_name))
            os.makedirs(os.path.dirname(target_path), exist_ok=True)

            with zf.open(entry, 'r') as src, open(target_path, 'wb') as dst:
                shutil.copyfileobj(src, dst)

            extracted_files.append(norm_name)

    return sorted(extracted_files)
