import fnmatch

def authorize(request: dict, policies: list[dict]) -> bool:
    if not isinstance(request, dict):
        return False

    req_keys = ['subject_id', 'tenant_id', 'resource_tenant_id', 'roles', 'action', 'resource', 'context']
    if not all(k in request for k in req_keys):
        return False

    for k in ['subject_id', 'tenant_id', 'resource_tenant_id', 'action', 'resource']:
        if not request[k]:
            return False

    if not isinstance(request['roles'], list) or not request['roles']:
        return False

    if not all(isinstance(r, str) for r in request['roles']):
        return False

    if not isinstance(request['context'], dict):
        return False

    if request['tenant_id'] != request['resource_tenant_id']:
        return False

    if not isinstance(policies, list):
        return False

    for p in policies:
        if not isinstance(p, dict):
            return False
        if p.get('effect') not in ('allow', 'deny'):
            return False
        if 'tenant' not in p:
            return False
        if not isinstance(p.get('roles'), list) or not p['roles']:
            return False
        if not isinstance(p.get('actions'), list) or not p['actions']:
            return False
        if not isinstance(p.get('resources'), list) or not p['resources']:
            return False
        if 'conditions' in p and not isinstance(p['conditions'], dict):
            return False

    allowed = False
    req_tenant = request['tenant_id']
    req_roles = set(request['roles'])
    req_action = str(request['action'])
    req_resource = str(request['resource'])
    req_context = request['context']

    for p in policies:
        # Tenant match
        if p['tenant'] != req_tenant and p['tenant'] != '*':
            continue

        # Role match
        if '*' not in p['roles'] and not req_roles.intersection(p['roles']):
            continue

        # Action match
        if not any(fnmatch.fnmatchcase(req_action, str(act)) for act in p['actions']):
            continue

        # Resource match
        if not any(fnmatch.fnmatchcase(req_resource, str(res)) for res in p['resources']):
            continue

        # Conditions match
        cond_match = True
        if 'conditions' in p:
            for k, v in p['conditions'].items():
                if k not in req_context:
                    cond_match = False
                    break

                req_val = req_context[k]
                if isinstance(v, list):
                    if req_val not in v:
                        cond_match = False
                        break
                else:
                    if req_val != v:
                        cond_match = False
                        break

        if cond_match:
            if p['effect'] == 'deny':
                return False
            else:
                allowed = True

    return allowed
