import decimal
from decimal import Decimal

class _PaymentState:
    def __init__(self, payment_id):
        self.payment_id = payment_id
        self.next_sequence = 1
        self.authorized = Decimal('0.00')
        self.captured = Decimal('0.00')
        self.refunded = Decimal('0.00')
        self.reversed = Decimal('0.00')
        self.buffer = {}
        self.applied_events = {}

    def copy(self):
        new_state = _PaymentState(self.payment_id)
        new_state.next_sequence = self.next_sequence
        new_state.authorized = self.authorized
        new_state.captured = self.captured
        new_state.refunded = self.refunded
        new_state.reversed = self.reversed
        new_state.buffer = self.buffer.copy()
        new_state.applied_events = self.applied_events.copy()
        return new_state

    def apply_single_event(self, event):
        seq = event['sequence']
        if seq != self.next_sequence:
            raise ValueError("Sequence mismatch")

        ev_type = event['type']
        amt = Decimal(event['amount'])

        if seq == 1:
            if ev_type != 'authorized':
                raise ValueError("Sequence 1 must authorize")
            self.authorized = amt
        else:
            if ev_type == 'authorized':
                raise ValueError("Cannot authorize more than once")

            if ev_type == 'captured':
                if self.captured + amt > self.authorized:
                    raise ValueError("Captures cannot exceed authorization")
                self.captured += amt
            elif ev_type == 'refunded':
                merchant_balance = self.captured - self.refunded - self.reversed
                if amt > merchant_balance:
                    raise ValueError("Refunds cannot exceed merchant balance")
                self.refunded += amt
            elif ev_type == 'reversed':
                merchant_balance = self.captured - self.refunded - self.reversed
                if amt > merchant_balance:
                    raise ValueError("Reversals cannot exceed merchant balance")
                self.reversed += amt

        self.applied_events[seq] = event
        self.next_sequence += 1

    def to_dict(self) -> dict:
        available = self.authorized - self.captured
        merchant_balance = self.captured - self.refunded - self.reversed

        q = Decimal('0.01')
        return {
            'authorized': str(self.authorized.quantize(q)),
            'captured': str(self.captured.quantize(q)),
            'refunded': str(self.refunded.quantize(q)),
            'reversed': str(self.reversed.quantize(q)),
            'available_to_capture': str(available.quantize(q)),
            'merchant_balance': str(merchant_balance.quantize(q)),
            'next_sequence': self.next_sequence
        }


class PaymentLedger:
    def __init__(self):
        self.seen_events = {}
        self.payments = {}

    def _validate_event(self, event: dict):
        if not isinstance(event, dict):
            raise ValueError("Event must be a dict")

        expected_keys = {'event_id', 'payment_id', 'sequence', 'type', 'amount'}
        if set(event.keys()) != expected_keys:
            raise ValueError("Event must have exactly the required fields")

        try:
            hash(event['event_id'])
            hash(event['payment_id'])
        except TypeError:
            raise ValueError("event_id and payment_id must be hashable")

        if type(event['sequence']) is not int or event['sequence'] <= 0:
            raise ValueError("Sequence must be a positive integer")

        if event['type'] not in {'authorized', 'captured', 'refunded', 'reversed'}:
            raise ValueError("Invalid type")

        amt = event['amount']
        if type(amt) is not str:
            raise ValueError("Amount must be a string")

        if 'e' in amt.lower():
            raise ValueError("Scientific notation not allowed")

        try:
            d = Decimal(amt)
        except decimal.InvalidOperation:
            raise ValueError("Invalid decimal string")

        if not d.is_finite() or d <= 0:
            raise ValueError("Amount must be positive and finite")

        if d.as_tuple().exponent < -2:
            raise ValueError("At most two fractional digits allowed")

    def apply(self, event: dict) -> str:
        self._validate_event(event)

        # Shallow copy to freeze internal state against caller mutations
        event_copy = dict(event)
        event_id = event_copy['event_id']
        payment_id = event_copy['payment_id']
        seq = event_copy['sequence']

        if event_id in self.seen_events:
            if self.seen_events[event_id] == event_copy:
                return 'duplicate'
            else:
                raise ValueError("Event ID reused with different content")

        pay_state = self.payments.get(payment_id)
        if pay_state is None:
            pay_state = _PaymentState(payment_id)

        if seq < pay_state.next_sequence or seq in pay_state.buffer:
            raise ValueError("Sequence reused with different content")

        if seq > pay_state.next_sequence:
            if payment_id not in self.payments:
                self.payments[payment_id] = pay_state
            pay_state.buffer[seq] = event_copy
            self.seen_events[event_id] = event_copy
            return 'buffered'

        temp_state = pay_state.copy()
        temp_state.apply_single_event(event_copy)

        curr_seq = seq + 1
        while curr_seq in temp_state.buffer:
            buf_ev = temp_state.buffer.pop(curr_seq)
            temp_state.apply_single_event(buf_ev)
            curr_seq += 1

        self.payments[payment_id] = temp_state
        self.seen_events[event_id] = event_copy
        return 'applied'

    def state(self, payment_id) -> dict | None:
        if payment_id not in self.payments:
            return None
        return self.payments[payment_id].to_dict()

    def snapshot(self) -> dict:
        return {
            pid: self.state(pid)
            for pid in sorted(self.payments.keys())
        }
