class RetryableError(Exception):
    pass

class FatalError(Exception):
    pass

class CrashError(Exception):
    pass


class SagaOrchestrator:
    def __init__(self, executor, compensator, max_retries: int = 2, journal: dict | None = None):
        self.executor = executor
        self.compensator = compensator
        self.max_retries = max_retries
        self.journal = {} if journal is None else journal

    def _validate_and_init(self, saga_id: str, steps: list[str]):
        if not isinstance(steps, list):
            raise TypeError("Steps must be a list")

        seen = set()
        for s in steps:
            if not isinstance(s, str) or not s:
                raise ValueError("Steps must be unique non-empty strings")
            if s in seen:
                raise ValueError("Steps must be unique non-empty strings")
            seen.add(s)

        if saga_id in self.journal:
            if self.journal[saga_id]["steps"] != steps:
                raise ValueError("Changed step plan for an existing saga")
        else:
            self.journal[saga_id] = {
                "steps": list(steps),
                "completed_steps": [],
                "compensated_steps": [],
                "state": "forward"
            }

    def _update_journal(self, saga_id: str, **kwargs):
        current = self.journal[saga_id]
        new_state = dict(current)
        for k, v in kwargs.items():
            new_state[k] = v
        self.journal[saga_id] = new_state

    def run(self, saga_id: str, steps: list[str]) -> str:
        return self._execute(saga_id, steps)

    def recover(self, saga_id: str, steps: list[str]) -> str:
        return self._execute(saga_id, steps)

    def _execute(self, saga_id: str, steps: list[str]) -> str:
        self._validate_and_init(saga_id, steps)

        state_info = self.journal[saga_id]

        if state_info["state"] == "completed":
            return "completed"
        if state_info["state"] == "compensated":
            return "compensated"

        if state_info["state"] == "forward":
            for step in steps:
                state_info = self.journal[saga_id]
                if step in state_info["completed_steps"]:
                    continue

                success = False
                retries = 0
                while not success:
                    try:
                        self.executor(step)
                        success = True
                    except RetryableError:
                        if retries < self.max_retries:
                            retries += 1
                        else:
                            self._update_journal(saga_id, state="compensating")
                            break
                    except CrashError:
                        raise
                    except Exception:
                        self._update_journal(saga_id, state="compensating")
                        break

                state_info = self.journal[saga_id]
                if state_info["state"] == "compensating":
                    break

                if success:
                    new_completed = list(state_info["completed_steps"])
                    new_completed.append(step)
                    self._update_journal(saga_id, completed_steps=new_completed)

            state_info = self.journal[saga_id]
            if state_info["state"] == "forward":
                self._update_journal(saga_id, state="completed")
                return "completed"

        state_info = self.journal[saga_id]
        if state_info["state"] == "compensating":
            for step in reversed(state_info["completed_steps"]):
                state_info = self.journal[saga_id]
                if step in state_info["compensated_steps"]:
                    continue

                success = False
                retries = 0
                while not success:
                    try:
                        self.compensator(step)
                        success = True
                    except RetryableError:
                        if retries < self.max_retries:
                            retries += 1
                        else:
                            raise FatalError(f"Compensator exhausted retries for step {step}")
                    except CrashError:
                        raise
                    except Exception:
                        raise

                if success:
                    new_compensated = list(state_info["compensated_steps"])
                    new_compensated.append(step)
                    self._update_journal(saga_id, compensated_steps=new_compensated)

            self._update_journal(saga_id, state="compensated")
            return "compensated"
